#!/usr/bin/env python3
# ruff: noqa: TID251
import argparse
import json
import os
import re
import shutil
import subprocess
import sys
import tempfile
import urllib.error
import urllib.parse
import urllib.request
from dataclasses import dataclass
from pathlib import Path

LIBRARY_FILE_ID_XATTR_NAME = "user.library-file-id"


class LibraryFileTransferError(Exception):
    pass


def require_object(value: object, label: str) -> dict[str, object]:
    if not isinstance(value, dict):
        raise LibraryFileTransferError(f"{label} must be a JSON object")
    result: dict[str, object] = {}
    for key, item in value.items():
        if not isinstance(key, str):
            raise LibraryFileTransferError(f"{label} keys must be strings")
        result[key] = item
    return result


def require_string(value: object, label: str, *, allow_empty: bool = False) -> str:
    if not isinstance(value, str) or (not allow_empty and not value):
        qualification = "" if allow_empty else " non-empty"
        raise LibraryFileTransferError(f"{label} must be a{qualification} string")
    return value


@dataclass(frozen=True)
class ExtendedAttribute:
    name: str
    value: str

    @classmethod
    def parse(cls, value: object, index: int) -> "ExtendedAttribute":
        payload = require_object(value, f"xattrs[{index}]")
        return cls(
            name=require_string(payload.get("name"), f"xattrs[{index}].name"),
            value=require_string(
                payload.get("value"),
                f"xattrs[{index}].value",
                allow_empty=True,
            ),
        )

    def apply(self, path: Path) -> None:
        encoded_value = self.value.encode()
        if sys.platform == "darwin":
            actual_value = self._apply_darwin(path, encoded_value)
        else:
            os.setxattr(path, self.name, encoded_value)
            actual_value = os.getxattr(path, self.name)
        if actual_value != encoded_value:
            raise LibraryFileTransferError(f"failed to verify extended attribute {self.name!r}")

    def _apply_darwin(self, path: Path, encoded_value: bytes) -> bytes:
        try:
            subprocess.run(
                ["/usr/bin/xattr", "-wx", self.name, encoded_value.hex(), path],
                check=True,
                capture_output=True,
            )
            result = subprocess.run(
                ["/usr/bin/xattr", "-px", self.name, path],
                check=True,
                capture_output=True,
                text=True,
            )
        except subprocess.CalledProcessError as exc:
            raise LibraryFileTransferError(
                f"failed to apply extended attribute {self.name!r}"
            ) from exc
        return bytes.fromhex(result.stdout)


def parse_xattrs(value: object) -> tuple[ExtendedAttribute, ...]:
    if not isinstance(value, list):
        raise LibraryFileTransferError("xattrs must be a JSON array")
    return tuple(ExtendedAttribute.parse(item, index) for index, item in enumerate(value))


def include_library_file_id_xattr(
    xattrs: tuple[ExtendedAttribute, ...],
    library_file_id: str | None,
) -> tuple[ExtendedAttribute, ...]:
    if library_file_id is None:
        return xattrs
    return (
        *(xattr for xattr in xattrs if xattr.name != LIBRARY_FILE_ID_XATTR_NAME),
        ExtendedAttribute(name=LIBRARY_FILE_ID_XATTR_NAME, value=library_file_id),
    )


def _is_trusted_estuary_download(download_url: str) -> bool:
    download = urllib.parse.urlsplit(download_url)
    hosted_apps = urllib.parse.urlsplit(
        os.environ.get("CODEX_APPS_MCP_URL", "https://chatgpt.com/backend-api/wham/apps")
    )
    try:
        same_origin = (download.hostname, 443 if download.port is None else download.port) == (
            hosted_apps.hostname,
            443 if hosted_apps.port is None else hosted_apps.port,
        )
    except ValueError:
        return False
    prefix = "/backend-api/estuary/public_content/enc/"
    return (
        download.scheme == hosted_apps.scheme == "https"
        and same_origin
        and download.username is None
        and download.password is None
        and download.path.startswith(prefix)
        and re.fullmatch(r"[A-Za-z0-9_-]+={0,2}", download.path[len(prefix) :]) is not None
        and not download.query
        and not download.fragment
    )


def _estuary_auth_headers(download_url: str) -> dict[str, str]:
    if not _is_trusted_estuary_download(download_url):
        return {}
    authorization = os.environ.get("CODEX_APPS_AUTHORIZATION", "").strip()
    account_id = os.environ.get("CODEX_APPS_CHATGPT_ACCOUNT_ID", "").strip()
    if not authorization:
        token = os.environ.get("CODEX_CONNECTORS_TOKEN", "").strip()
        if not token:
            auth_path = Path(
                os.environ.get("CODEX_AUTH_PATH")
                or Path(os.environ.get("CODEX_HOME", Path.home() / ".codex")) / "auth.json"
            ).expanduser()
            try:
                payload = require_object(json.loads(auth_path.read_text()), "Codex auth")
                tokens = require_object(payload.get("tokens"), "Codex auth tokens")
                token = require_string(tokens.get("access_token"), "Codex access token")
                if token == "access_token":
                    return {}
                account_id = account_id or str(tokens.get("account_id") or "")
            except (OSError, json.JSONDecodeError, LibraryFileTransferError):
                return {}
        authorization = f"Bearer {token}"
    headers = {"Authorization": authorization}
    if account_id:
        headers["ChatGPT-Account-ID"] = account_id
    return headers


class _NoAuthenticatedRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, *_args: object) -> None:
        return None


@dataclass(frozen=True)
class LibraryFileTransfer:
    download_url: str
    headers: dict[str, str]
    library_file_id: str | None
    xattrs: tuple[ExtendedAttribute, ...]

    @classmethod
    def parse(cls, value: object) -> "LibraryFileTransfer":
        payload = require_object(value, "transfer")
        raw_headers = require_object(payload.get("headers", {}), "transfer.headers")
        headers = {
            name: require_string(header_value, f"transfer.headers[{name!r}]")
            for name, header_value in raw_headers.items()
        }
        return cls(
            download_url=require_string(payload.get("download_url"), "transfer.download_url"),
            headers=headers,
            library_file_id=(
                require_string(payload["library_file_id"], "transfer.library_file_id")
                if payload.get("library_file_id") is not None
                else None
            ),
            xattrs=parse_xattrs([] if payload.get("xattrs") is None else payload["xattrs"]),
        )

    def write_to(self, destination: Path) -> None:
        headers = {} if _is_trusted_estuary_download(self.download_url) else self.headers
        request = urllib.request.Request(self.download_url, headers=headers, method="GET")
        auth_headers = _estuary_auth_headers(self.download_url)
        for name, value in auth_headers.items():
            request.add_unredirected_header(name, value)
        urlopen = (
            urllib.request.build_opener(_NoAuthenticatedRedirect()).open
            if auth_headers
            else urllib.request.urlopen
        )
        try:
            with (
                urlopen(request, timeout=300) as response,
                destination.open("wb") as output,
            ):
                shutil.copyfileobj(response, output)
        except urllib.error.HTTPError as exc:
            raise LibraryFileTransferError(f"download failed with HTTP status {exc.code}") from exc
        except urllib.error.URLError as exc:
            raise LibraryFileTransferError("download failed") from exc


class LibraryFileMaterializer:
    def materialize(self, transfer: LibraryFileTransfer, destination: Path) -> None:
        self._require_absolute_path(destination)
        destination.parent.mkdir(parents=True, exist_ok=True)
        file_descriptor, temporary_name = tempfile.mkstemp(
            dir=destination.parent,
            prefix=f".{destination.name}.",
        )
        os.close(file_descriptor)
        temporary_path = Path(temporary_name)
        try:
            transfer.write_to(temporary_path)
            self.apply_xattrs(
                include_library_file_id_xattr(
                    transfer.xattrs,
                    transfer.library_file_id,
                ),
                temporary_path,
            )
            os.replace(temporary_path, destination)
        finally:
            temporary_path.unlink(missing_ok=True)

    def apply_xattrs(
        self,
        xattrs: tuple[ExtendedAttribute, ...],
        path: Path,
    ) -> None:
        self._require_absolute_path(path)
        if not path.is_file():
            raise LibraryFileTransferError(f"file does not exist: {path}")
        for xattr in xattrs:
            xattr.apply(path)

    @staticmethod
    def _require_absolute_path(path: Path) -> None:
        if not path.is_absolute():
            raise LibraryFileTransferError("file path must be absolute")


def load_stdin_json() -> object:
    if sys.stdin.isatty():
        raise LibraryFileTransferError("stdin must be closed after one complete JSON request")
    try:
        value: object = json.load(sys.stdin)
    except json.JSONDecodeError as exc:
        raise LibraryFileTransferError("stdin must contain valid JSON") from exc
    return value


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Materialize a ChatGPT Library transfer and preserve its extended attributes.",
    )
    subparsers = parser.add_subparsers(dest="command", required=True)
    materialize_parser = subparsers.add_parser("materialize")
    materialize_parser.add_argument("destination", type=Path)
    apply_parser = subparsers.add_parser("apply-xattrs")
    apply_parser.add_argument("path", type=Path)
    apply_parser.add_argument("library_file_id")
    return parser


def main(argv: list[str]) -> int:
    args = build_parser().parse_args(argv)
    materializer = LibraryFileMaterializer()
    try:
        if args.command == "materialize":
            materializer.materialize(
                LibraryFileTransfer.parse(load_stdin_json()),
                args.destination,
            )
            print(args.destination)
        else:
            materializer.apply_xattrs(
                include_library_file_id_xattr(
                    parse_xattrs(load_stdin_json()),
                    require_string(args.library_file_id, "library_file_id"),
                ),
                args.path,
            )
            print(args.path)
    except (LibraryFileTransferError, OSError) as exc:
        print(f"library file transfer failed: {exc}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))

#!/usr/bin/env python3
# ruff: noqa: TID251
import json
import os
import socket
import ssl
import urllib.error
import urllib.request
from dataclasses import dataclass
from pathlib import Path
from threading import Lock


class HostedAppsError(Exception):
    pass


class HostedAppsToolError(HostedAppsError):
    def __init__(self, message: str, result: dict[str, object]) -> None:
        super().__init__(message)
        self.result = result


_MAX_TOOL_LIST_PAGES = 100


def _url_error_category(reason: object) -> str:
    if isinstance(reason, TimeoutError):
        return "timeout"
    if isinstance(reason, socket.gaierror):
        return "DNS"
    if isinstance(reason, ssl.SSLError):
        return "TLS"
    if isinstance(reason, ConnectionError):
        return "connection"
    return "network"


def _require_object(value: object, label: str) -> dict[str, object]:
    if not isinstance(value, dict):
        raise HostedAppsError(f"{label} must be a JSON object")
    if not all(isinstance(key, str) for key in value):
        raise HostedAppsError(f"{label} keys must be strings")
    return value


def _require_string(value: object, label: str) -> str:
    if not isinstance(value, str) or not value:
        raise HostedAppsError(f"{label} must be a non-empty string")
    return value


@dataclass(frozen=True)
class HostedAppTool:
    name: str
    meta: dict[str, object]


class HostedAppsClient:
    """Call authenticated hosted-app tools from the active Codex session."""

    def __init__(self) -> None:
        self.endpoint = os.environ.get(
            "CODEX_APPS_MCP_URL",
            "https://chatgpt.com/backend-api/wham/apps",
        )
        self._request_id = 0
        self._request_id_lock = Lock()
        self._tools: list[HostedAppTool] = []
        self._tool_lock = Lock()

    def call_tool(
        self,
        connector_id: str,
        tool_name: str,
        arguments: dict[str, object],
    ) -> dict[str, object]:
        tool = self._tool(connector_id, tool_name)
        params: dict[str, object] = {
            "name": tool.name,
            "arguments": arguments,
        }
        request_meta = self._request_meta(tool.meta)
        if request_meta:
            params["_meta"] = request_meta
        result = self._rpc("tools/call", params)
        if result.get("isError") is True:
            raise HostedAppsToolError(f"{tool_name} failed", result)
        return result

    def _tool(self, connector_id: str, tool_name: str) -> HostedAppTool:
        with self._tool_lock:
            tool = self._find_tool(connector_id, tool_name)
            return tool or self._load_tool(connector_id, tool_name)

    def _find_tool(
        self,
        connector_id: str,
        tool_name: str,
    ) -> HostedAppTool | None:
        return next(
            (tool for tool in self._tools if self._is_tool(tool, connector_id, tool_name)),
            None,
        )

    def _load_tool(self, connector_id: str, tool_name: str) -> HostedAppTool:
        cursor: str | None = None
        seen_cursors: set[str] = set()
        for _ in range(_MAX_TOOL_LIST_PAGES):
            params: dict[str, object] = {}
            if cursor is not None:
                params["cursor"] = cursor
            result = self._rpc("tools/list", params)
            tools = result.get("tools")
            if not isinstance(tools, list):
                raise HostedAppsError("hosted apps tools/list did not return a tools array")
            discovered: list[HostedAppTool] = []
            for index, tool_value in enumerate(tools):
                tool = _require_object(tool_value, f"tools[{index}]")
                name = tool.get("name")
                meta = tool.get("_meta")
                if not isinstance(name, str) or not name or not isinstance(meta, dict):
                    continue
                discovered.append(
                    HostedAppTool(
                        name=name,
                        meta=meta,
                    )
                )
            self._tools.extend(discovered)
            matched_tool = self._find_tool(connector_id, tool_name)
            if matched_tool is not None:
                return matched_tool
            next_cursor = result.get("nextCursor", result.get("next_cursor"))
            if not isinstance(next_cursor, str) or not next_cursor:
                break
            if next_cursor in seen_cursors:
                raise HostedAppsError("hosted apps tools/list cursor repeated")
            seen_cursors.add(next_cursor)
            cursor = next_cursor
        raise HostedAppsError(f"Library {tool_name} is not available")

    @staticmethod
    def _is_tool(
        tool: HostedAppTool,
        connector_id: str,
        tool_name: str,
    ) -> bool:
        discovered_connector_id = next(
            (
                tool.meta.get(key)
                for key in ("connector_id", "connectorId", "app_id", "appId")
                if tool.meta.get(key) is not None
            ),
            None,
        )
        return discovered_connector_id == connector_id and (
            tool.name == tool_name
            or tool.name.endswith(f"_{tool_name}")
            or tool.name.endswith(f".{tool_name}")
        )

    def _rpc(
        self,
        method: str,
        params: dict[str, object],
    ) -> dict[str, object]:
        with self._request_id_lock:
            self._request_id += 1
            request_id = self._request_id
        body = json.dumps(
            {
                "jsonrpc": "2.0",
                "id": request_id,
                "method": method,
                "params": params,
            },
            separators=(",", ":"),
        ).encode()
        request = urllib.request.Request(
            self.endpoint,
            data=body,
            headers={
                "Accept": "application/json, text/event-stream",
                "Content-Type": "application/json",
                **self._auth_headers(),
            },
            method="POST",
        )
        try:
            with urllib.request.urlopen(
                request,
                timeout=90,
                context=self._ssl_context(),
            ) as response:
                response_body = response.read().decode()
                content_type = response.headers.get("content-type", "")
        except urllib.error.HTTPError as exc:
            raise HostedAppsError(
                f"hosted apps {method} request failed with HTTP status {exc.code}"
            ) from exc
        except urllib.error.URLError as exc:
            raise HostedAppsError(
                f"hosted apps {method} request failed: {_url_error_category(exc.reason)}"
            ) from exc
        payload = self._decode_response(response_body, content_type)
        if payload.get("error") is not None:
            raise HostedAppsError(f"hosted apps {method} RPC failed")
        return _require_object(payload.get("result"), "hosted apps RPC result")

    @staticmethod
    def _request_meta(tool_meta: dict[str, object]) -> dict[str, object]:
        request_meta = dict(tool_meta)
        thread_id = os.environ.get("CODEX_THREAD_ID", "").strip()
        if thread_id:
            request_meta["threadId"] = thread_id
        session_id = os.environ.get("CODEX_SESSION_ID", "").strip()
        if thread_id and session_id and session_id != thread_id:
            existing_turn_metadata = request_meta.get("x-codex-turn-metadata")
            turn_metadata = (
                dict(existing_turn_metadata) if isinstance(existing_turn_metadata, dict) else {}
            )
            turn_metadata["session_id"] = session_id
            turn_metadata["thread_id"] = thread_id
            # The gateway reads the outer IDs for request correlation. It only
            # forwards declared first-party action metadata from mcp_request_meta.
            existing_action_meta = turn_metadata.get("mcp_request_meta")
            action_meta = (
                dict(existing_action_meta) if isinstance(existing_action_meta, dict) else {}
            )
            action_meta["x-codex-turn-metadata"] = {
                "session_id": session_id,
                "thread_id": thread_id,
            }
            turn_metadata["mcp_request_meta"] = action_meta
            request_meta["x-codex-turn-metadata"] = turn_metadata
        return request_meta

    def _auth_headers(self) -> dict[str, str]:
        account_id = os.environ.get("CODEX_APPS_CHATGPT_ACCOUNT_ID", "").strip() or None
        authorization = os.environ.get("CODEX_APPS_AUTHORIZATION", "").strip()
        if authorization:
            return self._with_account_id(authorization, account_id)
        connector_token = os.environ.get("CODEX_CONNECTORS_TOKEN", "").strip()
        if connector_token:
            return self._with_account_id(f"Bearer {connector_token}", account_id)
        token, auth_account_id = self._auth_file_tokens()
        return self._with_account_id(
            f"Bearer {token}",
            account_id or auth_account_id,
        )

    @staticmethod
    def _with_account_id(
        authorization: str,
        account_id: str | None,
    ) -> dict[str, str]:
        headers = {"Authorization": authorization}
        if account_id is not None:
            headers["ChatGPT-Account-ID"] = account_id
        return headers

    @staticmethod
    def _auth_file_tokens() -> tuple[str, str | None]:
        configured_path = os.environ.get("CODEX_AUTH_PATH")
        if configured_path:
            auth_path = Path(configured_path).expanduser()
        elif os.environ.get("CODEX_HOME"):
            auth_path = Path(os.environ["CODEX_HOME"]).expanduser() / "auth.json"
        else:
            auth_path = Path.home() / ".codex" / "auth.json"
        try:
            payload: object = json.loads(auth_path.read_text(encoding="utf-8"))
            auth = _require_object(payload, "Codex auth")
            tokens = _require_object(auth.get("tokens"), "Codex auth tokens")
            token = _require_string(tokens.get("access_token"), "Codex access token")
            account_value = tokens.get("account_id")
            account_id = (
                _require_string(account_value, "Codex account id")
                if account_value is not None
                else None
            )
        except (OSError, json.JSONDecodeError, HostedAppsError) as exc:
            raise HostedAppsError(f"could not read Codex auth from {auth_path}") from exc
        return token, account_id

    @staticmethod
    def _ssl_context() -> ssl.SSLContext:
        for environment_name in (
            "SSL_CERT_FILE",
            "REQUESTS_CA_BUNDLE",
            "CURL_CA_BUNDLE",
        ):
            ca_bundle = os.environ.get(environment_name)
            if ca_bundle:
                return ssl.create_default_context(cafile=ca_bundle)
        default_ca_bundle = Path("/etc/ssl/certs/ca-certificates.crt")
        if default_ca_bundle.exists():
            return ssl.create_default_context(cafile=default_ca_bundle)
        return ssl.create_default_context()

    @classmethod
    def _decode_response(
        cls,
        body: str,
        content_type: str,
    ) -> dict[str, object]:
        if "text/event-stream" not in content_type.lower():
            try:
                value: object = json.loads(body)
            except json.JSONDecodeError as exc:
                raise HostedAppsError("hosted apps returned invalid JSON") from exc
            return _require_object(value, "hosted apps response")

        last_event: dict[str, object] | None = None
        data_lines: list[str] = []
        for line in (*body.splitlines(), ""):
            if not line:
                event = cls._decode_event(data_lines)
                if event is not None:
                    last_event = event
                data_lines = []
            elif line.startswith("data:"):
                data_lines.append(line.removeprefix("data:").lstrip())
        if last_event is None:
            raise HostedAppsError("hosted apps returned an empty event stream")
        return last_event

    @staticmethod
    def _decode_event(data_lines: list[str]) -> dict[str, object] | None:
        if not data_lines:
            return None
        candidate = "\n".join(data_lines)
        if candidate.strip() == "[DONE]":
            return None
        try:
            value: object = json.loads(candidate)
        except json.JSONDecodeError:
            return None
        return value if isinstance(value, dict) else None

#!/usr/bin/env python3
# ruff: noqa: TID251
import json
import mimetypes
import os
import shutil
import subprocess
import sys
import tempfile
import urllib.error
import urllib.parse
import urllib.request
from collections.abc import Iterator
from concurrent.futures import Future, ThreadPoolExecutor
from dataclasses import dataclass
from pathlib import Path
from typing import TypeVar

# Managed runtimes can enable PYTHONSAFEPATH, which omits the script directory
# even for an absolute entrypoint. Only bundled sibling modules are added.
SCRIPT_DIRECTORY = Path(__file__).resolve().parent
if str(SCRIPT_DIRECTORY) not in sys.path:
    sys.path.insert(0, str(SCRIPT_DIRECTORY))

from library_file_transfer import (  # noqa: E402
    LibraryFileMaterializer,
    LibraryFileTransferError,
    _NoAuthenticatedRedirect,
    include_library_file_id_xattr,
    parse_xattrs,
    require_object,
    require_string,
)
from library_hosted_apps import (  # noqa: E402
    HostedAppsClient,
    HostedAppsError,
    HostedAppsToolError,
)


class LibraryUploadError(Exception):
    pass


_LIBRARY_CONNECTOR_ID = "connector_openai_library"
_LIBRARY_ARTIFACT_TYPES = {"other", "image", "image_gen", "report", "sheet", "slides"}
_APP_BATCH_SIZE = 20
_DEFAULT_TRANSFER_CONCURRENCY = 20
_SMALL_TRANSFER_CONCURRENCY = 100
_SMALL_FILE_BYTES = 1024 * 1024
_SMALL_BATCH_BYTES = 100 * 1024 * 1024
_ESTUARY_UPLOAD_PATH = "/backend-api/estuary/upload_content_bytes"
_ESTUARY_UPLOAD_TIMEOUT_SECONDS = 300
_MAX_SHARED_UPLOAD_BYTES = 512 * 1024 * 1024
_LIBRARY_FILE_WRITE_RECEIPT_PREFIX = "__OPENAI_LIBRARY_FILE_WRITE_RECEIPT_V1__="
_SHARED_PREPARE_FALLBACK_ERRORS = {
    "Library prepare_uploads is not available",
    "prepare_uploads failed",
}
T = TypeVar("T")


@dataclass(frozen=True)
class UploadRequest:
    index: int
    local_path: Path
    purpose: str
    library_file_id: str | None
    library_file_name: str | None
    directory_id: str | None
    expected_current_version: int | None
    version_reason: str | None
    size_bytes: int
    mime_type: str | None
    library_artifact_type: str | None
    is_shared: bool

    @classmethod
    def parse(
        cls,
        value: object,
        index: int,
    ) -> "UploadRequest":
        payload = require_object(value, f"uploads[{index}]")
        unexpected_keys = set(payload) - {
            "local_path",
            "purpose",
            "library_file_id",
            "library_file_name",
            "directory_id",
            "expected_current_version",
            "version_reason",
            "is_shared",
            "library_artifact_type",
        }
        if unexpected_keys:
            raise LibraryUploadError(f"uploads[{index}] contains unsupported fields")

        local_path = Path(require_string(payload.get("local_path"), f"uploads[{index}].local_path"))
        if not local_path.is_absolute():
            raise LibraryUploadError(f"uploads[{index}].local_path must be absolute")
        if not local_path.is_file():
            raise LibraryUploadError(f"uploads[{index}].local_path must name a file")

        purpose = require_string(payload.get("purpose"), f"uploads[{index}].purpose")
        if purpose not in {"create_library_file", "replace_library_file"}:
            raise LibraryUploadError(f"uploads[{index}].purpose is unsupported")

        library_artifact_type = cls._optional_string(
            payload.get("library_artifact_type"),
            f"uploads[{index}].library_artifact_type",
        )
        if library_artifact_type is not None:
            if library_artifact_type not in _LIBRARY_ARTIFACT_TYPES:
                raise LibraryUploadError(f"uploads[{index}].library_artifact_type is unsupported")
            if purpose != "create_library_file":
                raise LibraryUploadError("Replacement uploads cannot change library_artifact_type")

        library_file_id = cls._optional_string(
            payload.get("library_file_id"),
            f"uploads[{index}].library_file_id",
        )
        library_file_name = cls._optional_string(
            payload.get("library_file_name"),
            f"uploads[{index}].library_file_name",
        )
        directory_id = cls._optional_string(
            payload.get("directory_id"),
            f"uploads[{index}].directory_id",
        )
        expected_current_version = cls._optional_version(
            payload.get("expected_current_version"),
            f"uploads[{index}].expected_current_version",
        )
        version_reason = cls._optional_string(
            payload.get("version_reason"),
            f"uploads[{index}].version_reason",
        )
        is_shared = payload.get("is_shared", False)
        if not isinstance(is_shared, bool):
            raise LibraryUploadError(f"uploads[{index}].is_shared must be a boolean")
        if purpose == "replace_library_file" and library_file_id is None:
            raise LibraryUploadError(f"uploads[{index}] replacement requires library_file_id")
        if purpose == "create_library_file" and (
            library_file_id is not None
            or library_file_name is not None
            or expected_current_version is not None
            or version_reason is not None
            or is_shared
        ):
            raise LibraryUploadError(f"uploads[{index}] create cannot include replacement metadata")

        mime_type, _ = mimetypes.guess_type(local_path.name)
        size_bytes = local_path.stat().st_size
        if is_shared:
            if size_bytes > _MAX_SHARED_UPLOAD_BYTES:
                raise LibraryUploadError(f"uploads[{index}] exceeds the maximum shared upload size")
            if expected_current_version is None:
                try:
                    stored_id, stored_version = (
                        bytes.fromhex(
                            subprocess.run(
                                ["/usr/bin/xattr", "-px", name, local_path],
                                check=True,
                                capture_output=True,
                                text=True,
                            ).stdout
                        )
                        if sys.platform == "darwin"
                        else os.getxattr(local_path, name)
                        for name in ("user.library-file-id", "user.library-file-version")
                    )
                    if (
                        stored_id != (library_file_id or "").encode()
                        or not stored_version.isdigit()
                        or len(stored_version) > 19
                    ):
                        raise ValueError
                    expected_current_version = int(stored_version)
                    if (
                        expected_current_version > 2**63 - 1
                        or stored_version != str(expected_current_version).encode()
                    ):
                        raise ValueError
                except (
                    AttributeError,
                    NotImplementedError,
                    OSError,
                    subprocess.CalledProcessError,
                    ValueError,
                ):
                    raise LibraryUploadError(
                        f"uploads[{index}] shared replacement requires expected_current_version"
                    ) from None
            if directory_id is not None:
                raise LibraryUploadError(f"uploads[{index}] shared replacement cannot move files")
        return cls(
            index=index,
            local_path=local_path,
            purpose=purpose,
            library_file_id=library_file_id,
            library_file_name=library_file_name,
            directory_id=directory_id,
            expected_current_version=expected_current_version,
            version_reason=version_reason,
            size_bytes=size_bytes,
            mime_type=mime_type,
            library_artifact_type=library_artifact_type,
            is_shared=is_shared,
        )

    @property
    def prepare_payload(self) -> dict[str, object]:
        payload: dict[str, object] = {
            "file_name": self.local_path.name,
            "purpose": self.purpose,
            "file_size_bytes": self.size_bytes,
            "workspace_path": str(self.local_path),
        }
        if self.mime_type is not None:
            payload["mime_type"] = self.mime_type
        if self.library_artifact_type is not None:
            payload["library_artifact_type"] = self.library_artifact_type
        if self.is_shared:
            payload["file_name"] = self.library_file_name or self.local_path.name
            payload["library_file_id"] = self.library_file_id
            payload["expected_current_version"] = self.expected_current_version
        return payload

    @staticmethod
    def _optional_string(value: object, label: str) -> str | None:
        if value is None:
            return None
        return require_string(value, label)

    @staticmethod
    def _optional_version(value: object, label: str) -> int | None:
        if value is None:
            return None
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            raise LibraryUploadError(f"{label} must be a non-negative integer")
        return value


@dataclass(frozen=True)
class PreparedUpload:
    request: UploadRequest
    payload: dict[str, object]
    transfer_mode: str

    @classmethod
    def parse(
        cls,
        request: UploadRequest,
        value: object,
    ) -> "PreparedUpload":
        payload = require_object(value, f"uploads[{request.index}] result")
        fields = {
            name: payload[name]
            for name in (
                "upload_session_id",
                "file_id",
                "file_name",
                "upload_url",
                "workspace_path",
                "method",
                "required_headers",
                "purpose",
                "store_in_library",
                "mime_type",
                "library_artifact_type",
                "file_size_bytes",
                "library_file_id",
                "expected_current_version",
                "shared_library_upload",
                "pdf_c2pa_upload",
            )
            if name in payload
        }
        for name in ("upload_session_id", "file_id", "file_name"):
            require_string(fields.get(name), f"prepared upload {name}")
        purpose = require_string(fields.get("purpose"), "prepared upload purpose")
        if purpose != request.purpose:
            raise LibraryUploadError("prepare_uploads returned a mismatched purpose")
        if fields.get("library_artifact_type") != request.library_artifact_type:
            raise LibraryUploadError("prepare_uploads returned a mismatched library_artifact_type")
        if not isinstance(fields.get("store_in_library"), bool):
            raise LibraryUploadError("prepare_uploads omitted its retention mode")
        if request.is_shared:
            if fields.get("shared_library_upload") is not True:
                raise LibraryUploadError("prepare_uploads omitted the shared upload marker")
            if fields.get("library_file_id") != request.library_file_id:
                raise LibraryUploadError("prepare_uploads returned a mismatched shared file")
            version = UploadRequest._optional_version(
                fields.get("expected_current_version"),
                "prepared shared upload version",
            )
            if version != request.expected_current_version:
                raise LibraryUploadError("prepare_uploads returned a mismatched shared version")
            if fields["store_in_library"] or fields.get("pdf_c2pa_upload", False) is not False:
                raise LibraryUploadError("prepare_uploads returned an invalid shared upload")
        elif fields.get("shared_library_upload") is not None:
            raise LibraryUploadError("prepare_uploads returned an unexpected shared upload marker")
        if fields.get("method", "PUT") != "PUT":
            raise LibraryUploadError("prepare_uploads returned an unsupported method")

        upload_url = fields.get("upload_url")
        workspace_path = fields.get("workspace_path")
        if (upload_url is None) == (workspace_path is None):
            raise LibraryUploadError("prepare_uploads must return exactly one transfer mode")
        if upload_url is not None:
            require_string(upload_url, "prepared upload URL")
            raw_headers = require_object(
                fields.get("required_headers", {}),
                "prepared upload headers",
            )
            fields["required_headers"] = {
                name: require_string(value, f"prepared upload header {name!r}")
                for name, value in raw_headers.items()
            }
            transfer_mode = "upload_url"
        else:
            path = Path(require_string(workspace_path, "prepared workspace path"))
            if not path.is_absolute():
                raise LibraryUploadError("prepared workspace path must be absolute")
            transfer_mode = "workspace_path"
        return cls(request=request, payload=fields, transfer_mode=transfer_mode)

    @property
    def finalize_payload(self) -> dict[str, object]:
        payload = dict(self.payload)
        if self.request.directory_id is not None:
            payload["directory_id"] = self.request.directory_id
        if self.request.purpose == "replace_library_file":
            payload["library_file_id"] = self.request.library_file_id
            if self.request.expected_current_version is not None:
                payload["expected_current_version"] = self.request.expected_current_version
            if self.request.version_reason is not None:
                payload["version_reason"] = self.request.version_reason
        return payload


class SignedUrlUploader:
    """Transfer signed-URL items without exposing their transport details."""

    def upload(
        self,
        uploads: tuple[PreparedUpload, ...],
        state_directory: Path,
    ) -> set[int]:
        if not uploads:
            return set()
        executable: str | None = None
        environment: dict[str, str] = {}
        if any(not self._is_estuary_upload(upload) for upload in uploads):
            executable = shutil.which("azcopy")
            if executable is None and Path("/usr/local/bin/azcopy").is_file():
                executable = "/usr/local/bin/azcopy"
            if executable is not None:
                logs_directory = state_directory / "logs"
                jobs_directory = state_directory / "jobs"
                logs_directory.mkdir(mode=0o700)
                jobs_directory.mkdir(mode=0o700)
                environment = {
                    **os.environ,
                    "AZCOPY_LOG_LOCATION": str(logs_directory),
                    "AZCOPY_JOB_PLAN_LOCATION": str(jobs_directory),
                    "AZCOPY_CONCURRENCY_VALUE": os.environ.get(
                        "AZCOPY_CONCURRENCY_VALUE",
                        "16",
                    ),
                }
        worker_count = min(len(uploads), self._concurrency(uploads))
        with ThreadPoolExecutor(max_workers=worker_count) as executor:
            futures: dict[Future[bool], int] = {
                executor.submit(
                    self._upload_one,
                    executable,
                    upload,
                    state_directory,
                    environment,
                ): upload.request.index
                for upload in uploads
            }
            return {index for future, index in futures.items() if future.result()}

    @staticmethod
    def _concurrency(uploads: tuple[PreparedUpload, ...]) -> int:
        if (
            all(upload.request.size_bytes < _SMALL_FILE_BYTES for upload in uploads)
            and sum(upload.request.size_bytes for upload in uploads) < _SMALL_BATCH_BYTES
        ):
            return _SMALL_TRANSFER_CONCURRENCY
        return _DEFAULT_TRANSFER_CONCURRENCY

    @staticmethod
    def _upload_one(
        executable: str | None,
        upload: PreparedUpload,
        state_directory: Path,
        environment: dict[str, str],
    ) -> bool:
        if SignedUrlUploader._is_estuary_upload(upload):
            return SignedUrlUploader._upload_estuary(upload)
        if executable is None:
            return False
        upload_url = require_string(upload.payload.get("upload_url"), "prepared upload URL")
        destination = urllib.parse.urlsplit(upload_url)
        required_headers = require_object(
            upload.payload.get("required_headers", {}), "prepared upload headers"
        )
        transfer_options: list[str] = []
        if (
            destination.scheme == "https"
            and (destination.hostname or "").endswith(".oaiusercontent.com")
            and any(
                name.lower() == "x-ms-blob-type" and value == "BlockBlob"
                for name, value in required_headers.items()
            )
        ):
            # Public aliases need an explicit Azure type and requests below the edge size limit.
            # This selects transport options for the returned URL; it grants no destination access.
            transfer_options = [
                "--from-to=LocalBlob",
                "--blob-type=BlockBlob",
                "--block-size-mb=64",
                "--put-blob-size-mb=64",
            ]
        log_path = state_directory / f"transfer-{upload.request.index}.log"
        try:
            with log_path.open("xb") as output:
                result = subprocess.run(
                    [
                        executable,
                        "copy",
                        str(upload.request.local_path),
                        upload_url,
                        "--overwrite=true",
                        "--output-type=json",
                        *transfer_options,
                    ],
                    check=False,
                    env=environment,
                    stdout=output,
                    stderr=subprocess.STDOUT,
                )
        except OSError:
            return False
        return result.returncode == 0

    @staticmethod
    def _is_estuary_upload(upload: PreparedUpload) -> bool:
        destination = urllib.parse.urlsplit(
            require_string(upload.payload.get("upload_url"), "prepared upload URL")
        )
        hosted_apps = urllib.parse.urlsplit(
            os.environ.get("CODEX_APPS_MCP_URL", "https://chatgpt.com/backend-api/wham/apps")
        )
        try:
            same_origin = (
                destination.hostname,
                443 if destination.port is None else destination.port,
            ) == (
                hosted_apps.hostname,
                443 if hosted_apps.port is None else hosted_apps.port,
            )
        except ValueError:
            return False
        return (
            destination.scheme == hosted_apps.scheme == "https"
            and same_origin
            and destination.username is None
            and destination.password is None
            and destination.path == _ESTUARY_UPLOAD_PATH
            and not destination.fragment
        )

    @staticmethod
    def _upload_estuary(upload: PreparedUpload) -> bool:
        upload_url = require_string(upload.payload.get("upload_url"), "prepared upload URL")
        required_headers = require_object(
            upload.payload.get("required_headers", {}),
            "prepared upload headers",
        )
        headers = {
            "Content-Length": str(upload.request.size_bytes),
            **{
                name: require_string(value, f"prepared upload header {name!r}")
                for name, value in required_headers.items()
            },
        }
        if upload.request.mime_type is not None:
            headers.setdefault("Content-Type", upload.request.mime_type)
        try:
            with upload.request.local_path.open("rb") as body:
                request = urllib.request.Request(
                    upload_url, data=body, headers=headers, method="PUT"
                )
                with urllib.request.urlopen(
                    request,
                    timeout=_ESTUARY_UPLOAD_TIMEOUT_SECONDS,
                    context=HostedAppsClient._ssl_context(),
                ) as response:
                    response.read()
                    return 200 <= response.status < 300
        except OSError:
            return False


class LibraryUploadWorkflow:
    def __init__(
        self,
        apps_client: HostedAppsClient,
        materializer: LibraryFileMaterializer,
        uploader: SignedUrlUploader,
        *,
        state_parent: Path = Path("/tmp"),
    ) -> None:
        self.apps_client = apps_client
        self.materializer = materializer
        self.uploader = uploader
        self.state_parent = state_parent
        self._publish_all_receipts = False

    def run(self, value: object) -> dict[str, object]:
        requests = self._parse_requests(value)
        self._publish_all_receipts = len(requests) <= _APP_BATCH_SIZE
        prepared, prepare_failures, prepare_fallbacks = self._prepare(requests)

        results: list[dict[str, object] | None] = [
            prepare_failures.get(index) for index in range(len(requests))
        ]
        url_uploads = tuple(upload for upload in prepared if upload.transfer_mode == "upload_url")
        with tempfile.TemporaryDirectory(
            prefix="openai-library-upload-",
            dir=self.state_parent,
        ) as state_directory_value:
            transferred_url_indices = (
                self.uploader.upload(
                    url_uploads,
                    Path(state_directory_value),
                )
                if url_uploads
                else set()
            )

            for upload in url_uploads:
                if upload.request.index not in transferred_url_indices:
                    results[upload.request.index] = {
                        "local_path": str(upload.request.local_path),
                        "purpose": upload.request.purpose,
                        "status": "failed",
                        "error_code": "transfer_failed",
                        "message": "file transfer failed",
                    }

            prepared_by_index = {
                upload.request.index: upload
                for upload in prepared
                if upload.transfer_mode == "workspace_path"
                or upload.request.index in transferred_url_indices
            }
            pending: list[PreparedUpload] = []
            for request in requests:
                if not request.is_shared:
                    if (upload := prepared_by_index.get(request.index)) is not None:
                        pending.append(upload)
                    continue
                for upload, result in self._finalize(tuple(pending)):
                    results[upload.request.index] = self._result(upload, result)
                pending.clear()
                if (shared_upload := prepared_by_index.get(request.index)) is None:
                    if request.index in prepare_failures:
                        continue
                    if request.index in prepare_fallbacks or results[request.index] is not None:
                        results[request.index] = self._shared_result(request)
                    continue
                try:
                    finalized = self._finalize((shared_upload,))
                except HostedAppsError as error:
                    if str(error) != "finalize_uploads failed":
                        raise
                    finalized = [
                        (
                            shared_upload,
                            {
                                "operation": request.purpose,
                                "status": "failed",
                                "error_code": "operation_failed",
                            },
                        )
                    ]
                for upload, result in finalized:
                    shared_result = self._result(upload, result)
                    if (
                        shared_result.get("status") == "failed"
                        and shared_result.get("error_code") == "operation_failed"
                    ):
                        shared_result = self._shared_result(request)
                        if shared_result.get("status") != "succeeded":
                            shared_result["error_code"] = "commit_unknown"
                            shared_result["message"] = "Library finalization failed"
                    results[upload.request.index] = shared_result
            for upload, result in self._finalize(tuple(pending)):
                results[upload.request.index] = self._result(upload, result)

        if any(result is None for result in results):
            raise LibraryUploadError("upload results are incomplete")
        return {"results": [result for result in results if result is not None]}

    def _parse_requests(self, value: object) -> tuple[UploadRequest, ...]:
        payload = require_object(value, "upload request")
        if set(payload) != {"uploads"}:
            raise LibraryUploadError("upload request must contain only uploads")
        uploads_value = payload.get("uploads")
        if not isinstance(uploads_value, list) or not uploads_value:
            raise LibraryUploadError("uploads must be a non-empty array")
        return tuple(
            UploadRequest.parse(upload, index) for index, upload in enumerate(uploads_value)
        )

    def _prepare(
        self,
        requests: tuple[UploadRequest, ...],
    ) -> tuple[
        tuple[PreparedUpload, ...],
        dict[int, dict[str, object]],
        frozenset[int],
    ]:
        prepared: list[PreparedUpload] = []
        failures: dict[int, dict[str, object]] = {}
        fallbacks: set[int] = set()
        for batch in self._prepare_batches(requests):
            try:
                response = self.apps_client.call_tool(
                    _LIBRARY_CONNECTOR_ID,
                    "prepare_uploads",
                    {"uploads": [request.prepare_payload for request in batch]},
                )
            except HostedAppsError as error:
                request = batch[0] if len(batch) == 1 and batch[0].is_shared else None
                if request is not None and isinstance(error, HostedAppsToolError):
                    conflict_result = self._prepare_conflict_result(request, error)
                    if conflict_result is not None:
                        failures[request.index] = conflict_result
                        continue
                if request is not None and str(error) in _SHARED_PREPARE_FALLBACK_ERRORS:
                    fallbacks.add(request.index)
                else:
                    raise
                continue
            values = self._result_array(response, "uploads")
            if len(values) != len(batch):
                raise LibraryUploadError("prepare_uploads returned an unexpected number of uploads")
            prepared.extend(
                PreparedUpload.parse(request, value)
                for request, value in zip(batch, values, strict=True)
            )
        return tuple(prepared), failures, frozenset(fallbacks)

    def _prepare_conflict_result(
        self,
        request: UploadRequest,
        error: HostedAppsToolError,
    ) -> dict[str, object] | None:
        if not request.is_shared:
            return None
        structured_content = error.result.get("structuredContent")
        if not isinstance(structured_content, dict):
            return None
        error_data = structured_content.get("error_data")
        if (
            not isinstance(error_data, dict)
            or error_data.get("code") != "conflict"
            or error_data.get("reason") != "version_conflict"
        ):
            return None
        return self._failed_result(
            request,
            {
                "operation": request.purpose,
                "status": "failed",
                "error_code": "conflict",
                "error_data": error_data,
            },
        )

    @classmethod
    def _prepare_batches(
        cls,
        requests: tuple[UploadRequest, ...],
    ) -> tuple[tuple[UploadRequest, ...], ...]:
        batches: list[tuple[UploadRequest, ...]] = []
        pending: list[UploadRequest] = []
        for request in requests:
            if request.is_shared:
                batches.extend(cls._batches(tuple(pending)))
                pending.clear()
                batches.append((request,))
            else:
                pending.append(request)
        batches.extend(cls._batches(tuple(pending)))
        return tuple(batches)

    def _finalize(
        self,
        uploads: tuple[PreparedUpload, ...],
    ) -> list[tuple[PreparedUpload, dict[str, object]]]:
        finalized: list[tuple[PreparedUpload, dict[str, object]]] = []
        for batch in self._batches(uploads):
            response = self.apps_client.call_tool(
                _LIBRARY_CONNECTOR_ID,
                "finalize_uploads",
                {"uploads": [upload.finalize_payload for upload in batch]},
            )
            values = self._result_array(response, "results")
            if len(values) != len(batch):
                raise LibraryUploadError(
                    "finalize_uploads returned an unexpected number of results"
                )
            finalized.extend(
                (upload, require_object(value, "finalize upload result"))
                for upload, value in zip(batch, values, strict=True)
            )
        return finalized

    def _shared_result(self, request: UploadRequest) -> dict[str, object]:
        endpoint = urllib.parse.urlsplit(
            os.environ.get("CODEX_APPS_MCP_URL", "https://chatgpt.com/backend-api/wham/apps")
        )
        if endpoint.scheme != "https" or endpoint.netloc not in {
            "chatgpt.com",
            "chatgpt-staging.com",
        }:
            raise LibraryUploadError("shared replacement requires the official ChatGPT origin")
        library_file_id = require_string(request.library_file_id, "shared library_file_id")
        url = (
            f"https://{endpoint.netloc}/backend-api/files/library/shared/files/"
            f"{urllib.parse.quote(library_file_id, safe='')}"
        )
        headers: dict[str, str] = {"X-OpenAI-Library-Work-Replacement": "1"}
        authorization = os.environ.get("CODEX_APPS_AUTHORIZATION", "").strip()
        account_id = os.environ.get("CODEX_APPS_CHATGPT_ACCOUNT_ID", "").strip()
        if not authorization and not os.environ.get("CODEX_CONNECTORS_TOKEN", "").strip():
            try:
                token, auth_account_id = HostedAppsClient._auth_file_tokens()
                if token and token != "access_token":
                    authorization = f"Bearer {token}"
                    account_id = account_id or auth_account_id or ""
            except (HostedAppsError, OSError):
                pass
        if authorization:
            headers["Authorization"] = authorization
            if account_id:
                headers["ChatGPT-Account-ID"] = account_id
        opener = urllib.request.build_opener(
            urllib.request.HTTPSHandler(context=HostedAppsClient._ssl_context()),
            _NoAuthenticatedRedirect(),
        )
        boundary = os.urandom(16).hex()
        prefix = (
            f"--{boundary}\r\n"
            f'Content-Disposition: form-data; name="file"; '
            f"filename={json.dumps(request.local_path.name, ensure_ascii=False)}\r\n"
            f"Content-Type: {request.mime_type or 'application/octet-stream'}\r\n\r\n"
        ).encode()
        suffix = f"\r\n--{boundary}--\r\n".encode()

        def content() -> Iterator[bytes]:
            with request.local_path.open("rb") as source:
                initial = os.fstat(source.fileno())
                remaining = request.size_bytes
                if initial.st_size != remaining:
                    raise LibraryUploadError("shared replacement file changed")
                initial_state = (initial.st_size, initial.st_mtime_ns)
                yield prefix
                while remaining and (chunk := source.read(min(1024 * 1024, remaining))):
                    remaining -= len(chunk)
                    yield chunk
                final = os.fstat(source.fileno())
                if remaining or (final.st_size, final.st_mtime_ns) != initial_state:
                    raise LibraryUploadError("shared replacement file changed")
                yield suffix

        upload = PreparedUpload(request=request, payload={}, transfer_mode="workspace_path")
        method = "POST"
        try:
            upload_request = urllib.request.Request(
                f"{url}/upload",
                data=content(),
                headers={
                    **headers,
                    "Content-Type": f"multipart/form-data; boundary={boundary}",
                    "Content-Length": str(len(prefix) + request.size_bytes + len(suffix)),
                },
                method=method,
            )
            # Shared PDFs bypass C2PA signing; add signing in a follow-up.
            with opener.open(upload_request, timeout=_ESTUARY_UPLOAD_TIMEOUT_SECONDS) as response:
                staged = require_object(json.loads(response.read()), "shared upload result")
            body: dict[str, object] = {
                "source_file_id": require_string(staged.get("source_file_id"), "shared source id"),
                "expected_current_version": request.expected_current_version,
            }
            if request.version_reason is not None:
                body["version_reason"] = request.version_reason
            method = "PATCH"
            commit_request = urllib.request.Request(
                url,
                data=json.dumps(body, separators=(",", ":")).encode(),
                headers={**headers, "Content-Type": "application/json"},
                method=method,
            )
            with opener.open(commit_request, timeout=_ESTUARY_UPLOAD_TIMEOUT_SECONDS) as response:
                updated = require_object(json.loads(response.read()), "shared replacement result")
            if require_string(updated.get("id"), "shared replacement id") != library_file_id:
                raise LibraryUploadError("shared replacement returned a mismatched file")
            version = UploadRequest._optional_version(
                updated.get("current_version_number"),
                "shared replacement version",
            )
            if (
                version is None
                or request.expected_current_version is None
                or version != request.expected_current_version + 1
            ):
                raise LibraryUploadError("shared replacement returned an unexpected version")
            return self._result(
                upload,
                {
                    "operation": request.purpose,
                    "status": "succeeded",
                    "file_id": library_file_id,
                    "library_file_id": library_file_id,
                    "file_name": request.library_file_name or request.local_path.name,
                    "current_version_number": version,
                    "xattrs": [{"name": "user.library-file-version", "value": str(version)}],
                },
            )
        except urllib.error.HTTPError as error:
            error_code = {
                401: "access_denied",
                403: "access_denied",
                404: "not_found",
                409: "version_conflict",
            }.get(
                error.code,
                "commit_unknown" if method == "PATCH" and error.code >= 500 else "operation_failed",
            )
        except (OSError, LibraryFileTransferError, LibraryUploadError, json.JSONDecodeError):
            error_code = "commit_unknown" if method == "PATCH" else "transfer_failed"
        return self._result(
            upload,
            {"operation": request.purpose, "status": "failed", "error_code": error_code},
        )

    def _result(
        self,
        upload: PreparedUpload,
        value: dict[str, object],
    ) -> dict[str, object]:
        status = require_string(value.get("status"), "finalize upload status")
        operation = require_string(
            value.get("operation"),
            "finalize upload operation",
        )
        if operation != upload.request.purpose:
            raise LibraryUploadError("finalize_uploads returned a mismatched operation")
        if status == "failed":
            return self._failed_result(upload.request, value)
        if status != "succeeded":
            raise LibraryUploadError("finalize_uploads returned an unsupported status")

        library_file_id = require_string(
            value.get("library_file_id"),
            "finalize upload library_file_id",
        )
        file_id = require_string(value.get("file_id"), "finalize upload file_id")
        if upload.request.is_shared:
            if library_file_id != upload.request.library_file_id or file_id != library_file_id:
                raise LibraryUploadError("finalize_uploads returned a mismatched shared file")
            current_version = value.get("current_version_number")
            expected_version = upload.request.expected_current_version
            if (
                expected_version is None
                or isinstance(current_version, bool)
                or not isinstance(current_version, int)
                or current_version != expected_version + 1
            ):
                raise LibraryUploadError("finalize_uploads returned a mismatched shared version")
        metadata_applied = True
        try:
            self.materializer.apply_xattrs(
                include_library_file_id_xattr(
                    parse_xattrs(value.get("xattrs", [])),
                    library_file_id,
                ),
                upload.request.local_path,
            )
        except (LibraryFileTransferError, OSError):
            metadata_applied = False

        result: dict[str, object] = {
            "local_path": str(upload.request.local_path),
            "purpose": upload.request.purpose,
            "status": "succeeded",
            "file_id": file_id,
            "library_file_id": library_file_id,
            "file_name": require_string(
                value.get("file_name"),
                "finalize upload file_name",
            ),
            "local_metadata_applied": metadata_applied,
        }
        path = value.get("path")
        if path is not None:
            result["path"] = require_string(path, "finalize upload path")
        current_version = value.get("current_version_number")
        if current_version is not None:
            if (
                isinstance(current_version, bool)
                or not isinstance(current_version, int)
                or current_version < 0
            ):
                raise LibraryUploadError("finalize upload version must be a non-negative integer")
            result["current_version_number"] = current_version
        warnings = value.get("warnings")
        if warnings is not None:
            if not isinstance(warnings, list):
                raise LibraryUploadError("finalize upload warnings must be an array")
            result["warnings"] = [
                require_string(warning, "finalize upload warning") for warning in warnings
            ]
        if not upload.request.is_shared and (
            self._publish_all_receipts or upload.payload.get("pdf_c2pa_upload") is True
        ):
            try:
                receipt = json.dumps(
                    {
                        "sandbox_path": str(upload.request.local_path),
                        "file_id": result["file_id"],
                        "library_file_id": library_file_id,
                    },
                    separators=(",", ":"),
                )
                sys.stderr.write(f"{_LIBRARY_FILE_WRITE_RECEIPT_PREFIX}{receipt}\n")
                sys.stderr.flush()
            except (OSError, ValueError):
                pass
        return result

    @staticmethod
    def _failed_result(
        request: UploadRequest,
        value: dict[str, object],
    ) -> dict[str, object]:
        error_code = require_string(
            value.get("error_code"),
            "finalize upload error code",
        )
        result: dict[str, object] = {
            "local_path": str(request.local_path),
            "purpose": request.purpose,
            "status": "failed",
            "error_code": error_code,
            "message": (
                "Library file version conflict."
                if error_code == "version_conflict"
                else "Library finalization failed"
            ),
        }
        error_data = value.get("error_data")
        if (
            error_code == "conflict"
            and isinstance(error_data, dict)
            and error_data.get("reason") == "version_conflict"
        ):
            conflict: dict[str, object] = {
                "code": "conflict",
                "reason": "version_conflict",
                "failure_stage": "version_check",
                "retryable": False,
                "recovery": "refresh_and_reapply",
            }
            for field in ("expected_current_version", "current_version_number"):
                version = error_data.get(field)
                conflict[field] = version if type(version) is int and version >= 0 else None
            result["error_data"] = conflict
            result["message"] = (
                "Library file version conflict. Refresh the Library file and reapply your changes "
                "only if still valid; do not retry the stale write."
            )
        return result

    @staticmethod
    def _result_array(value: object, field: str) -> list[object]:
        payload = require_object(value, "hosted app result")
        structured_content = payload.get("structuredContent")
        if structured_content is not None:
            result = require_object(
                structured_content,
                "hosted app structured content",
            ).get(field)
            if not isinstance(result, list):
                raise LibraryUploadError(f"{field} must be an array")
            return result

        content = payload.get("content")
        if isinstance(content, list):
            for index, item in enumerate(content):
                try:
                    content_item = require_object(item, f"content[{index}]")
                    text_payload = require_object(
                        json.loads(
                            require_string(
                                content_item.get("text"),
                                f"content[{index}].text",
                            )
                        ),
                        f"content[{index}].text payload",
                    )
                    result = text_payload.get(field)
                    if not isinstance(result, list):
                        continue
                    return result
                except (json.JSONDecodeError, LibraryFileTransferError):
                    continue
        raise LibraryUploadError(f"hosted app result does not contain {field}")

    @staticmethod
    def _batches(values: tuple[T, ...]) -> tuple[tuple[T, ...], ...]:
        return tuple(
            values[offset : offset + _APP_BATCH_SIZE]
            for offset in range(0, len(values), _APP_BATCH_SIZE)
        )


def main(argv: list[str]) -> int:
    if argv:
        print("usage: library_upload.py < request.json", file=sys.stderr)
        return 2
    if sys.stdin.isatty():
        print(
            "library upload failed: stdin must be closed after one JSON request",
            file=sys.stderr,
        )
        return 2
    try:
        try:
            request = json.load(sys.stdin)
        except json.JSONDecodeError as exc:
            raise LibraryUploadError("stdin must contain valid JSON") from exc
        result = LibraryUploadWorkflow(
            apps_client=HostedAppsClient(),
            materializer=LibraryFileMaterializer(),
            uploader=SignedUrlUploader(),
        ).run(request)
        print(json.dumps(result, separators=(",", ":")))
    except (
        HostedAppsError,
        LibraryFileTransferError,
        LibraryUploadError,
        OSError,
    ) as exc:
        print(f"library upload failed: {exc}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))

storageModules.content:
"""Retained storage for original receiving programmes using the native worker.

The caller owns its work directory. Native capacity, runtime consumers and
restorable cache retirement remain the existing Commons implementations.
"""
from __future__ import annotations

from contextlib import contextmanager
from datetime import datetime
import fcntl
import hashlib
import json
import os
from pathlib import Path
import stat
import tempfile
import time


CHUNK = 1024 * 1024


def canonical(value):
    return (json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":")) + "\n").encode()


def file_identity(path):
    path = Path(path)
    descriptor = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
    with os.fdopen(descriptor, "rb") as source:
        before = os.fstat(source.fileno())
        if not stat.S_ISREG(before.st_mode):
            raise ValueError("Select an original regular file: " + str(path))
        h = hashlib.sha256()
        for chunk in iter(lambda: source.read(CHUNK), b""):
            h.update(chunk)
        after = os.fstat(source.fileno())
    current = path.lstat()
    fields = ("st_dev", "st_ino", "st_size", "st_mtime_ns", "st_ctime_ns")
    if (not stat.S_ISREG(current.st_mode)
            or any(getattr(before, key) != getattr(after, key)
                   or getattr(after, key) != getattr(current, key) for key in fields)):
        raise ValueError("The selected file changed during reading: " + str(path))
    return {"path": str(path.resolve()), "bytes": after.st_size, "sha256": h.hexdigest()}


def sync_directory(directory):
    descriptor = os.open(directory, os.O_RDONLY | os.O_DIRECTORY)
    try:
        os.fsync(descriptor)
    finally:
        os.close(descriptor)


def private(directory):
    directory = Path(directory)
    directory.mkdir(mode=0o700, parents=True, exist_ok=True)
    info = directory.lstat()
    if (not stat.S_ISDIR(info.st_mode) or directory.is_symlink()
            or info.st_uid != os.getuid() or info.st_mode & 0o077
            or directory.resolve() != directory):
        raise ValueError("Use the original private receiving directory: " + str(directory))
    return directory


@contextmanager
def publication(destination, *, replace=False):
    """Write a complete temporary file, then expose it atomically."""
    destination = Path(destination)
    destination.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
    fd, name = tempfile.mkstemp(prefix="." + destination.name + ".", suffix=".pending",
                                dir=destination.parent)
    os.close(fd)
    temporary = Path(name)
    try:
        yield temporary
        with temporary.open("rb") as stream:
            os.fsync(stream.fileno())
        if replace:
            if destination.is_symlink():
                raise ValueError("The original receiving record became a link")
            os.replace(temporary, destination)
        else:
            try:
                os.link(temporary, destination, follow_symlinks=False)
            except FileExistsError:
                actual, expected = file_identity(destination), file_identity(temporary)
                if any(actual[key] != expected[key] for key in ("bytes", "sha256")):
                    raise ValueError("The original retained destination differs: " + str(destination))
        sync_directory(destination.parent)
    finally:
        temporary.unlink(missing_ok=True)


def save_bytes(path, body, *, replace=False):
    with publication(path, replace=replace) as temporary:
        with temporary.open("wb") as stream:
            stream.write(body)
            stream.flush()
            os.fsync(stream.fileno())


def save_json(path, value, *, replace=False):
    save_bytes(path, canonical(value), replace=replace)


def copy_file(source, destination, *, expected=None):
    source = Path(source)
    before = file_identity(source)
    if expected and any(before[key] != expected[key] for key in ("bytes", "sha256")):
        raise ValueError("The selected source bytes differ before staging")
    with publication(destination) as temporary:
        h = hashlib.sha256()
        size = 0
        with source.open("rb") as incoming, temporary.open("wb") as outgoing:
            for chunk in iter(lambda: incoming.read(CHUNK), b""):
                outgoing.write(chunk)
                h.update(chunk)
                size += len(chunk)
            outgoing.flush()
            os.fsync(outgoing.fileno())
        after = file_identity(source)
        if (size != before["bytes"] or h.hexdigest() != before["sha256"]
                or any(after[key] != before[key] for key in ("bytes", "sha256"))):
            raise ValueError("The original source changed while staging")
    return file_identity(destination)


def open_work(parent, identity, *, directory=None):
    """Reopen this caller's original directory and keep its sole lifetime lock."""
    parent = Path(parent).expanduser().resolve()
    key = hashlib.sha256(canonical(identity)).hexdigest()[:24]
    root = Path(directory).expanduser().resolve() if directory else parent / ("allium-receiving-" + key)
    existed = root.exists()
    if existed and (not root.is_dir() or root.is_symlink()):
        raise ValueError("The original work path is not a directory")
    marker = root / "receiving-storage.json"
    if existed and not marker.is_file():
        unexpected = [p.name for p in root.iterdir() if p.name != "receiving-storage.lock"
                      and not (p.name.startswith(".receiving-storage.json.") and p.name.endswith(".pending"))]
        if unexpected:
            raise ValueError("The work path contains files from another operation")
    private(root)
    handle = (root / "receiving-storage.lock").open("a+b")
    try:
        fcntl.flock(handle.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
        value = {"schema": "commons.receiving-storage/v1", "identity": identity,
                 "directory": str(root), "owner_uid": os.getuid()}
        save_json(marker, value)
        return root, handle
    except BaseException:
        handle.close()
        raise


def select_source_alias(work, identity, source):
    """Point only this receiver's convenience alias at its verified installation."""
    work, source = Path(work).resolve(), Path(source).resolve(strict=True)
    marker = json.loads((work / "receiving-storage.json").read_bytes())
    if marker.get("identity") != identity or marker.get("directory") != str(work):
        raise ValueError("The selected source alias is not this original operation")
    if not source.is_dir():
        raise ValueError("The verified native source is not a directory")
    alias = work / "source"
    previous = None
    if alias.exists() or alias.is_symlink():
        if not alias.is_symlink():
            raise ValueError("Preserve the existing original source directory")
        previous = os.readlink(alias)
        if alias.resolve() == source:
            return {"previous": previous, "source": str(source), "reused": True}
    selection = {"identity": identity, "alias": str(alias), "previous": previous,
                 "source": str(source)}
    key = hashlib.sha256(canonical(selection)).hexdigest()
    save_json(work / ("source-alias-" + key + ".json"), selection)
    temporary = work / (".source." + str(os.getpid()) + "." + str(time.time_ns()) + ".pending")
    try:
        temporary.symlink_to(source, target_is_directory=True)
        os.replace(temporary, alias)
        sync_directory(work)
    finally:
        temporary.unlink(missing_ok=True)
    return {**selection, "reused": False}


def storage_inventory(roles, *, processes=False, consumers=True):
    """Use the existing live cgroup/filesystem and native process observations."""
    roots = list(dict.fromkeys(str(Path(path).expanduser().resolve())
                               for values in roles.values() for path in values))
    try:
        from worker_capacity import snapshot
        observed = snapshot(roots, nearest_existing=True,
                            storage_roots=roots if consumers else None,
                            process_storage=processes)
    except ImportError:
        observed = {"provider": "portable receiving filesystem inventory", "filesystems": []}
        for selected in roots:
            anchor = Path(selected)
            while not anchor.exists() and anchor != anchor.parent:
                anchor = anchor.parent
            counters = os.statvfs(anchor)
            observed["filesystems"].append({"path": selected, "device": anchor.stat().st_dev,
                "available_bytes": counters.f_bavail * counters.f_frsize,
                "available_inodes": counters.f_favail})
        memory = {}
        for key in ("memory.current", "memory.max", "memory.events", "memory.stat"):
            source = Path("/sys/fs/cgroup") / key
            if source.is_file():
                memory[key] = source.read_text()
        observed["cgroup"] = memory
    return {"roles": {role: [str(Path(path).expanduser().resolve()) for path in paths]
                      for role, paths in roles.items()},
            "observed_at": time.time(),
            "native_record": os.environ.get("SWARM_NATIVE_RECORD"),
            "capacity": observed}


def runtime_candidates(customer_state, source_commit):
    """Read only this customer's retained original runtime observations."""
    if customer_state is None:
        return []
    directory = Path(customer_state) / "runtime-observations"
    if not directory.is_dir():
        return []
    rows = []
    for child in directory.iterdir():
        path = child / "runtime-resolution.json"
        if not child.is_dir() or child.is_symlink() or not path.is_file() or path.is_symlink():
            continue
        try:
            value = json.loads(path.read_bytes())
            if value.get("status") == "READY" and value.get("sourceCommit") == source_commit:
                runtime = Path(value["directory"])
                if runtime.is_absolute() and runtime.is_dir():
                    rows.append((path.stat().st_mtime_ns, str(runtime)))
        except (OSError, ValueError, KeyError, TypeError):
            continue
    return list(dict.fromkeys(path for _, path in sorted(rows, reverse=True)))


def uploaded_results(request, result):
    """Interpret the official per-file result; process exit zero is insufficient."""
    items = request.get("uploads", [])
    rows = result.get("results") if isinstance(result, dict) else None
    if not isinstance(rows, list) or len(rows) != len(items):
        raise ValueError("The upload result does not cover the complete selected delivery")
    accepted = []
    for selected, row in zip(items, rows):
        if (not isinstance(row, dict) or row.get("local_path") != selected["local_path"]
                or row.get("purpose") != selected["purpose"]):
            raise ValueError("An upload result belongs to a different selected file")
        if (row.get("status") == "succeeded" and isinstance(row.get("library_file_id"), str)
                and row["library_file_id"] and isinstance(row.get("file_id"), str) and row["file_id"]):
            accepted.append(row)
        elif row.get("status") != "failed":
            raise ValueError("An upload result has an unsupported completion state")
    return accepted


def save_uploads(request, path, invoke):
    """Save confirmed files once; explicit continuation submits only pending files."""
    path = Path(path)
    selection = [{**item, **{key: value for key, value in file_identity(item["local_path"]).items()
                             if key in ("bytes", "sha256")}} for item in request["uploads"]]
    previous = json.loads(path.read_bytes()) if path.is_file() else None
    if previous and previous.get("selection") != selection:
        raise ValueError("This upload continuation selects different original bytes")
    record = previous or {"schema": "commons.receiving-uploads/v1", "selection": selection,
                          "confirmed": [], "attempts": []}
    confirmed = {row["local_path"]: row for row in record["confirmed"]}
    for item in record["confirmed"]:
        uploaded_results({"uploads": [{"local_path": item["local_path"], "purpose": item["purpose"]}]},
                         {"results": [item]})
    pending = [item for item in request["uploads"] if item["local_path"] not in confirmed]
    if pending:
        current = {"uploads": pending}
        record["pending"] = pending
        save_json(path, record, replace=True)
        exit_code, raw = invoke(current)
        try:
            result = json.loads(raw)
            accepted = uploaded_results(current, result)
            for item in accepted:
                confirmed[item["local_path"]] = item
        except (ValueError, TypeError) as error:
            result = {"error": str(error), "response": raw.decode(errors="replace")
                      if isinstance(raw, bytes) else str(raw)}
        record["attempts"].append({"exit_code": exit_code, "result": result})
        record["confirmed"] = [confirmed[item["local_path"]] for item in request["uploads"]
                               if item["local_path"] in confirmed]
    record["pending"] = [item for item in request["uploads"] if item["local_path"] not in confirmed]
    record["complete"] = not record["pending"]
    save_json(path, record, replace=True)
    return record


def retire_copies(work, identity, entries, journal, *, reference):
    """Retire only selected owner-created file copies through native cache custody."""
    work, journal = Path(work).resolve(), Path(journal).resolve()
    marker = json.loads((work / "receiving-storage.json").read_bytes())
    if marker.get("identity") != identity or marker.get("directory") != str(work):
        raise ValueError("The selected cache is not this original receiving operation")
    try:
        from swarm_cloud_cache import create_plan, load_plan, retire
    except ImportError:
        return {"state": "retained", "operator": "swarm_cloud_cache",
                "work": str(work), "entries": entries, "reference": reference}
    selected = []
    for item in entries:
        target = Path(item["path"])
        if not target.is_absolute() or target.resolve() != target or not target.is_relative_to(work):
            raise ValueError("Retirement selects only exact private receiving paths")
        relative = target.relative_to(work).as_posix()
        first = Path(relative).parts[0]
        if (first in ("runtimes", "runtime", "delivery", "delivery-archives", "save-tools", "save-state")
                or first.startswith("runtime-")):
            raise ValueError("Retain original installations, deliverables and upload continuation")
        backing = file_identity(item["custody"])
        if target == Path(backing["path"]):
            raise ValueError("Retain the original backing file")
        custody = {"kind": "tar-member" if item.get("member") else "file",
                   "path": backing["path"], "size": backing["bytes"],
                   "sha256": backing["sha256"], "reference": reference}
        if item.get("member"):
            custody["member"] = item["member"]
        selected.append({"path": relative, "match": "complete", "custody": custody})
    if not selected:
        return {"entries": [], "allocated_bytes_released": 0}
    manifest = {"version": 1, "operation_id": identity["operation"], "cache_root": str(work),
                "strategy": "retire", "entries": selected}
    journal.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
    if not journal.exists():
        create_plan(manifest, journal)
    else:
        previous = load_plan(journal)
        previous_selection = [{"path": entry["path"], "match": entry["match"],
                               "custody": entry["custody"]} for entry in previous["entries"]]
        if (previous["operation_id"] != identity["operation"]
                or previous["cache_root"] != str(work)
                or previous.get("strategy", "retire") != "retire"
                or previous_selection != selected):
            raise ValueError("The existing retirement plan selects different original copies")
    return retire(journal, file_use=True)


# These placement observations augment the maintained worker snapshot. They are
# advisory; the original native memory/disk admission remains authoritative.
class StoragePlacementError(RuntimeError):
    def __init__(self, message, record):
        super().__init__(message)
        self.record = record


def _temporary_footprint(value):
    required = {"working_bytes", "working_inodes", "process_memory_bytes"}
    optional = {"reserve_bytes", "reserve_inodes", "reserve_memory_bytes"}
    if not isinstance(value, dict) or not required <= value.keys() or value.keys() - required - optional:
        raise ValueError("Specify the original working bytes, inodes and process-memory footprint")
    result = {key: value.get(key, 0) for key in sorted(required | optional)}
    if any(type(item) is not int or item < 0 for item in result.values()):
        raise ValueError("The original storage footprint uses nonnegative integer counters")
    if not result["working_bytes"] or not result["working_inodes"]:
        raise ValueError("The original working footprint must include bytes and inodes")
    return result


def _temporary_location(value):
    path = Path(value).expanduser()
    if not path.is_absolute():
        raise ValueError("Choose an absolute original temporary-volume path")
    path = Path(os.path.abspath(path))
    anchor = path
    while True:
        try:
            info = anchor.lstat()
            break
        except FileNotFoundError:
            if anchor == anchor.parent:
                raise
            anchor = anchor.parent
    if not stat.S_ISDIR(info.st_mode) or anchor.is_symlink() or anchor.resolve() != anchor:
        raise ValueError("The temporary-volume ancestor must be an existing real directory")
    return path, anchor


RECLAIM_OBSERVATION_MAX_AGE_SECONDS = 5.0


def _reclaim_estimate(capacity, now):
    """Estimate current-subtree reclaim without changing any kernel setting."""
    result = {"state": "unavailable", "estimated_bytes": 0,
              "clean_inactive_file_bytes": 0, "reclaimable_slab_bytes": 0,
              "errors": [], "maximum_age_seconds": RECLAIM_OBSERVATION_MAX_AGE_SECONDS}
    try:
        started = datetime.fromisoformat(capacity["started_at"].replace("Z", "+00:00"))
        finished = datetime.fromisoformat(capacity["finished_at"].replace("Z", "+00:00"))
        if started.tzinfo is None or finished.tzinfo is None:
            raise ValueError("timezone missing")
        start, end = started.timestamp(), finished.timestamp()
        if not start <= end <= now or now - start > RECLAIM_OBSERVATION_MAX_AGE_SECONDS:
            raise ValueError("observation outside freshness window")
    except (KeyError, TypeError, AttributeError, ValueError, OverflowError, OSError):
        result["errors"].append("reclaim_observation_stale_or_unobserved")
        return result
    group = capacity.get("cgroup_memory", {})
    levels = group.get("levels", [])
    current = levels[0].get("current_bytes") if levels else None
    counters = group.get("stat_bytes")
    names = ("file", "shmem", "inactive_file", "file_dirty", "file_writeback",
             "file_mapped", "slab", "slab_reclaimable", "slab_unreclaimable")
    if (type(current) is not int or current < 0 or not isinstance(counters, dict)
            or any(type(counters.get(key)) is not int or counters[key] < 0 for key in names)):
        result["errors"].append("reclaim_counters_unobserved")
        return result
    # file includes shmem. Inactive-file is a list counter, so bound it by
    # non-shmem file before conservatively excluding dirty/writeback/mapped.
    file_bytes = max(0, min(counters["inactive_file"],
                           max(0, counters["file"] - counters["shmem"]))
                     - counters["file_dirty"] - counters["file_writeback"]
                     - counters["file_mapped"])
    # slab is distinct from file; do not add slab's total and subtypes.
    slab_bytes = max(0, min(counters["slab_reclaimable"],
                           max(0, counters["slab"] - counters["slab_unreclaimable"])))
    estimate = min(current, file_bytes + slab_bytes)
    result.update(state="estimated", estimated_bytes=estimate,
                  clean_inactive_file_bytes=file_bytes,
                  reclaimable_slab_bytes=slab_bytes,
                  current_subtree_bytes=current,
                  observed_age_seconds=now - start,
                  counters={key: counters[key] for key in names})
    return result


def _memory_placement(capacity, now):
    """Keep raw bounds and an explicitly reclaim-dependent projection."""
    group = capacity.get("cgroup_memory", {})
    host = capacity.get("host_memory", {})
    levels = group.get("levels", [])
    reclaim = _reclaim_estimate(capacity, now)
    raw_ceilings, estimated_ceilings, bounds, errors = [], [], [], []
    if not levels:
        errors.append("current_cgroup_unobserved")
    for level in levels:
        used, maximum = level.get("current_bytes"), level.get("max_bytes")
        status = level.get("max_status")
        if type(used) is not int or used < 0 or status not in ("finite", "unlimited"):
            errors.append("cgroup_limit_unobserved")
        elif status == "finite":
            if type(maximum) is not int or maximum < 0:
                errors.append("cgroup_limit_unobserved")
            else:
                # The same current-subtree pages are inside every ancestor.
                # Project that one credit independently; never add ancestor credits.
                credit = min(used, reclaim["estimated_bytes"])
                raw = max(0, maximum - used)
                estimated = max(0, maximum - (used - credit))
                raw_ceilings.append(raw)
                estimated_ceilings.append(estimated)
                bounds.append({"directory": level.get("directory"),
                               "current_bytes": used, "max_bytes": maximum,
                               "uncommitted_headroom_bytes": raw,
                               "estimated_headroom_bytes": estimated,
                               "applied_reclaim_bytes": credit})
    available = host.get("available_bytes")
    if type(available) is int and available >= 0:
        raw_ceilings.append(available)
        estimated_ceilings.append(available)
    else:
        errors.append("host_availability_unobserved")
    raw = min(raw_ceilings) if raw_ceilings else None
    estimated = min(estimated_ceilings) if estimated_ceilings else None
    return {"state": "unavailable" if errors or not raw_ceilings else "observed",
            "headroom_bytes": estimated, "uncommitted_headroom_bytes": raw,
            "estimated_headroom_bytes": estimated,
            "estimated_reclaimable_bytes": reclaim["estimated_bytes"],
            "reclaim": reclaim, "cgroup_bounds": bounds,
            "protection_context": [{"directory": level.get("directory"),
                                    "protection": level.get("protection", {})}
                                   for level in levels],
            "host_available_bytes": available, "errors": errors}


def _placement_inventory(paths):
    """Project the maintained counters; estimated reclaim is not a reservation."""
    inventory = storage_inventory({"temporary": paths}, consumers=False)
    capacity = inventory["capacity"]
    memory = _memory_placement(capacity, time.time())
    rows = []
    for value in paths:
        path, anchor = _temporary_location(value)
        matches = [row for row in capacity.get("filesystems", [])
                   if row.get("requested_path") == str(path)]
        if len(matches) != 1:
            rows.append({"path": str(path), "state": "unavailable",
                         "reason": "original_filesystem_observation_required"})
            continue
        observed = matches[0]
        counters = (observed.get("available_bytes"), observed.get("inodes_available"))
        good = (observed.get("status") == "ok" and not observed.get("read_only", True)
                and observed.get("observed_path") == str(anchor)
                and type(observed.get("device")) is int
                and observed["device"] == anchor.stat().st_dev
                and all(type(number) is int and number >= 0 for number in counters)
                and isinstance(observed.get("mountpoint"), str)
                and isinstance(observed.get("filesystem"), str))
        rows.append({"path": str(path), "anchor": str(anchor),
                     "device": observed.get("device"), "filesystem": observed.get("filesystem"),
                     "mountpoint": observed.get("mountpoint"),
                     "available_bytes": counters[0], "available_inodes": counters[1],
                     "state": "observed" if good else "unavailable"})
    inventory["placement"] = {"state": "observed", "observed_at": time.time(),
                              "filesystems": rows, "memory": memory}
    return inventory


def _select_temporary_parent_observed(candidates, footprint, *, retained_directory=None,
                            same_process_save=False, memory_mode="raw"):
    """Choose before writing; a choice is not a native reservation.

    working_bytes/inodes describe additional simultaneous working capacity,
    including archive/upload staging. Recovery keeps this original request.
    process_memory_bytes is additional process working memory.
    """
    footprint = _temporary_footprint(footprint)
    if memory_mode not in ("raw", "kernel_reclaim"):
        raise ValueError("Memory mode must be raw or kernel_reclaim")
    if type(same_process_save) is not bool:
        raise ValueError("Declare whether the original caller retains same-process saving")
    original = None
    if retained_directory is not None:
        original, anchor = _temporary_location(retained_directory)
        if original != anchor:
            raise ValueError("Restore the original retained work directory before continuing")
        paths = [str(original)]
    else:
        if not isinstance(candidates, (tuple, list)) or not candidates:
            raise ValueError("Select at least one existing temporary-volume parent")
        paths = list(dict.fromkeys(str(_temporary_location(path)[0]) for path in candidates))
        for path in paths:
            selected, anchor = _temporary_location(path)
            if selected != anchor:
                raise ValueError("Temporary-volume candidates must already exist")
    inventory = _placement_inventory(paths)
    projection = inventory["placement"]
    memory = projection.get("memory", {})
    decisions = []
    for row in projection.get("filesystems", []):
        reasons = []
        ephemeral = row.get("filesystem") in {"tmpfs", "devtmpfs", "ramfs"}
        estimated = memory_mode == "kernel_reclaim" and not ephemeral
        admission_headroom = memory.get("estimated_headroom_bytes" if estimated
                                        else "uncommitted_headroom_bytes")
        required_memory = (footprint["process_memory_bytes"] + footprint["reserve_memory_bytes"]
                           + (footprint["working_bytes"] if ephemeral else 0))
        requires_reclaim = (required_memory > memory["uncommitted_headroom_bytes"]
                            if memory.get("state") == "observed" else None)
        if row.get("state") != "observed":
            reasons.append("filesystem_unobserved")
        else:
            if row["available_bytes"] < footprint["working_bytes"] + footprint["reserve_bytes"]:
                reasons.append("filesystem_bytes")
            if row["available_inodes"] < footprint["working_inodes"] + footprint["reserve_inodes"]:
                reasons.append("filesystem_inodes")
            if memory.get("state") != "observed":
                reasons.append("memory_unobserved")
            elif admission_headroom < required_memory:
                reasons.append("cgroup_or_host_memory")
            if ephemeral and not same_process_save:
                reasons.append("same_process_save_required")
        decision = {**row, "ephemeral": ephemeral, "reasons": reasons,
                    "required_memory_bytes": required_memory,
                    "requires_reclaim": requires_reclaim,
                    "admission_headroom_bytes": admission_headroom,
                    "memory_admission": ("estimated_kernel_reclaim"
                        if estimated and requires_reclaim else "uncommitted"),
                    "allocation_guaranteed": False}
        decisions.append(decision)
        if not reasons:
            return {"schema": "commons.receiving-temporary-choice/v1",
                    "parent": str(original.parent) if original else row["path"],
                    "retained_directory": str(original) if original else None,
                    "footprint": footprint, "same_process_save": same_process_save,
                    "memory_mode": memory_mode,
                    "selected": decision, "requires_reclaim": requires_reclaim,
                    "inventory": inventory}
    raise StoragePlacementError("No selected temporary volume admits the original working footprint",
        {"state": "PLACEMENT_UNAVAILABLE", "footprint": footprint,
         "retained_directory": str(original) if original else None,
         "decisions": decisions, "inventory": inventory})


DEFAULT_PLACEMENT_RECLAIM_BYTES = 256 * 1024 * 1024
MAX_PLACEMENT_RECLAIM_BYTES = 1024 * 1024 * 1024


def select_temporary_parent(candidates, footprint, *, retained_directory=None,
                            same_process_save=False, reclaim_bytes=0,
                            memory_mode="raw"):
    """Select storage with a retained, explicit process-memory admission mode.

    Raw headroom remains the default. An explicit kernel_reclaim choice may
    use the fresh conservative estimate on persistent filesystems only; Linux
    performs ordinary allocation-time reclamation under its unchanged limits.
    This estimate is never a reservation. Optional current-group reclaim and
    its actual result remain separate, including a read-only cgroup error.
    """
    if memory_mode not in ("raw", "kernel_reclaim"):
        raise ValueError("Memory mode must be raw or kernel_reclaim")
    if type(reclaim_bytes) is not int or not 0 <= reclaim_bytes <= MAX_PLACEMENT_RECLAIM_BYTES:
        raise ValueError("Placement reclaim budget must be 0..1073741824 bytes")
    try:
        choice = _select_temporary_parent_observed(candidates, footprint,
            retained_directory=retained_directory, same_process_save=same_process_save)
        choice["memory_mode"] = memory_mode
        return choice
    except StoragePlacementError as first:
        original = first.record
        projection = original.get("inventory", {}).get("placement", {})
        memory = projection.get("memory", {})
        eligible = [row for row in original.get("decisions", [])
                    if row.get("reasons") == ["cgroup_or_host_memory"]]
        if (not eligible or memory.get("state") != "observed"
                or (not reclaim_bytes and memory_mode == "raw")):
            raise
        reclaim = None
        if reclaim_bytes:
            retained_footprint = original["footprint"]
            deficits = [
                retained_footprint["process_memory_bytes"] + retained_footprint["reserve_memory_bytes"]
                + (retained_footprint["working_bytes"] if row["ephemeral"] else 0)
                - memory["uncommitted_headroom_bytes"] for row in eligible]
            requested = min(reclaim_bytes, min(deficits))
            if requested <= 0:
                raise
            reclaim = {"budget_bytes": reclaim_bytes, "requested_bytes": requested,
                       "original_inventory": original["inventory"],
                       "original_decisions": original["decisions"]}
            try:
                if __package__:
                    from .worker_capacity import reclaim_current_cgroup
                else:
                    from worker_capacity import reclaim_current_cgroup
                reclaim["result"] = reclaim_current_cgroup(requested,
                    expected_cgroup=original["inventory"]["capacity"].get("cgroup_memory", {}))
            except ImportError as error:
                reclaim["result"] = {"state": "UNAVAILABLE", "request_attempted": False,
                    "request_written": False,
                    "error": {"kind": type(error).__name__, "message": str(error)}}
            result = reclaim["result"]
            if (result.get("selection_cgroup_unchanged") is False
                    or result.get("current_cgroup_unchanged") is False):
                raise StoragePlacementError("The original current-cgroup identity changed during placement",
                    {**original, "state": "PLACEMENT_CHANGED", "capacity_reclaim": reclaim}) from first
        try:
            choice = _select_temporary_parent_observed(candidates, footprint,
                retained_directory=retained_directory, same_process_save=same_process_save,
                memory_mode=memory_mode)
        except StoragePlacementError as refreshed:
            if reclaim is not None:
                refreshed.record["capacity_reclaim"] = reclaim
            raise
        if reclaim is not None:
            choice["capacity_reclaim"] = reclaim
        return choice


def open_selected_work(identity, candidates, footprint, *, directory=None,
                       same_process_save=False,
                       reclaim_bytes=DEFAULT_PLACEMENT_RECLAIM_BYTES,
                       memory_mode="raw"):
    """Recheck the chosen volume, then retain the existing marker and work lock."""
    if memory_mode not in ("raw", "kernel_reclaim"):
        raise ValueError("Memory mode must be raw or kernel_reclaim")
    original = Path(directory).expanduser() if directory is not None else None
    if original is not None and not original.is_absolute():
        raise ValueError("Use the absolute original work directory")
    previous = None
    if original is None:
        key = hashlib.sha256(canonical(identity)).hexdigest()[:24]
        existing = []
        for parent in candidates:
            path, _ = _temporary_location(parent)
            possible = path / ("allium-receiving-" + key)
            if possible.exists() or possible.is_symlink():
                existing.append(possible)
        if len(set(existing)) > 1:
            raise ValueError("Select the authoritative original work directory; multiple copies exist")
        if existing:
            original = existing[0]
    if original is not None:
        original = Path(os.path.abspath(original))
        marker = original / "receiving-temporary.json"
        if marker.exists() or marker.is_symlink():
            file_identity(marker)
            previous = json.loads(marker.read_bytes())
            if (previous.get("schema") != "commons.receiving-temporary-placement/v1"
                    or previous.get("identity") != identity or previous.get("directory") != str(original)
                    or previous.get("footprint") != _temporary_footprint(footprint)
                    or previous.get("same_process_save") != same_process_save
                    or previous.get("memory_mode", "raw") != memory_mode):
                raise ValueError("Preserve the original receiving placement and working footprint")
        else:
            # open_work validates its existing identity marker or a setup that
            # stopped before publishing that marker. Do not choose a new root.
            retained_marker = original / "receiving-storage.json"
            if retained_marker.exists() or retained_marker.is_symlink():
                file_identity(retained_marker)
                retained = json.loads(retained_marker.read_bytes())
                if retained != {"schema": "commons.receiving-storage/v1", "identity": identity,
                                "directory": str(original), "owner_uid": os.getuid()}:
                    raise ValueError("The retained work directory belongs to another operation")
    choice = select_temporary_parent(candidates, footprint, retained_directory=original,
                                     same_process_save=same_process_save, reclaim_bytes=reclaim_bytes,
                                     memory_mode=memory_mode)
    # Selection has no reservation semantics. Reobserve the chosen device just
    # before open_work performs the first marker/lock/directory writes.
    try:
        fresh = select_temporary_parent([choice["parent"]], footprint, retained_directory=original,
                                        same_process_save=same_process_save, memory_mode=memory_mode)
    except StoragePlacementError as error:
        if "capacity_reclaim" in choice:
            error.record["capacity_reclaim"] = choice["capacity_reclaim"]
        error.record["original_choice"] = choice
        raise
    if "capacity_reclaim" in choice:
        fresh["capacity_reclaim"] = choice["capacity_reclaim"]
    if any(choice["selected"].get(key) != fresh["selected"].get(key)
           for key in ("device", "filesystem", "mountpoint")):
        raise StoragePlacementError("The selected temporary filesystem changed before setup",
                                    {"state": "PLACEMENT_CHANGED", "choice": choice, "fresh": fresh})
    if previous and any(previous.get(key) != fresh["selected"].get(key)
                        for key in ("device", "filesystem", "mountpoint")):
        raise StoragePlacementError("The original receiving filesystem identity changed",
                                    {"state": "PLACEMENT_CHANGED", "placement": previous, "fresh": fresh})
    root = handle = None
    try:
        root, handle = open_work(fresh["parent"], identity, directory=original)
        paths = {name: str(root / name) for name in ("temporary", "render", "archives", "save-state")}
        placement = {"schema": "commons.receiving-temporary-placement/v1", "identity": identity,
                     "directory": str(root), "footprint": fresh["footprint"],
                     "same_process_save": same_process_save,
                     **{key: fresh["selected"][key] for key in ("device", "filesystem", "mountpoint", "ephemeral")},
                     "paths": paths, "state_parent": paths["save-state"]}
        if memory_mode != "raw":
            placement["memory_mode"] = memory_mode
        if previous is not None and previous != placement:
            raise ValueError("Preserve the original receiving role paths")
        save_json(root / "receiving-temporary.json", placement)
        for path in paths.values():
            private(path)
            if Path(path).stat().st_dev != placement["device"]:
                raise ValueError("The original temporary role moved to another filesystem")
        save_json(root / ("placement-observation-" + str(time.time_ns()) + ".json"), fresh)
        return root, handle, placement
    except BaseException as error:
        failure = {"state": "PLACEMENT_SETUP_FAILED", "choice": fresh,
                   "directory": str(root) if root else None,
                   "error": {"name": type(error).__name__, "message": str(error)}}
        if root is not None:
            try:
                save_json(root / ("placement-failure-" + str(time.time_ns()) + ".json"), failure)
            except OSError as secondary:
                failure["record_error"] = {"name": type(secondary).__name__, "message": str(secondary)}
        if handle is not None:
            handle.close()
        if isinstance(error, (KeyboardInterrupt, SystemExit)):
            raise
        raise StoragePlacementError("Original temporary setup failed before product work", failure) from error


def temporary_environment(placement, environment=None):
    """Return child-only temporary bindings from the original prepared placement."""
    if placement.get("schema") != "commons.receiving-temporary-placement/v1":
        raise ValueError("Use this original caller's prepared temporary placement")
    result = dict(os.environ if environment is None else environment)
    temporary = placement["paths"]["temporary"]
    result.update(TMPDIR=temporary, TMP=temporary, TEMP=temporary)
    return result


def validate_temporary_placement(placement, *, refresh=False, reclaim_bytes=0):
    """Verify the retained role binding before an original launch or save."""
    if not isinstance(placement, dict) or placement.get("schema") != "commons.receiving-temporary-placement/v1":
        raise ValueError("Use the original prepared temporary placement")
    memory_mode = placement.get("memory_mode", "raw")
    if memory_mode not in ("raw", "kernel_reclaim"):
        raise ValueError("Memory mode must be raw or kernel_reclaim")
    root, anchor = _temporary_location(placement["directory"])
    if root != anchor:
        raise ValueError("Restore the original receiving directory before continuation")
    marker = root / "receiving-temporary.json"
    file_identity(marker)
    if json.loads(marker.read_bytes()) != placement:
        raise ValueError("The original temporary placement changed")
    for path in placement["paths"].values():
        selected, existing = _temporary_location(path)
        if selected != existing or root not in selected.parents or selected.stat().st_dev != placement["device"]:
            raise ValueError("The original temporary role binding changed")
    if placement["state_parent"] != placement["paths"]["save-state"]:
        raise ValueError("Preserve the original Library state_parent")
    if refresh:
        choice = select_temporary_parent([root.parent], placement["footprint"],
            retained_directory=root, same_process_save=placement["same_process_save"],
            reclaim_bytes=reclaim_bytes, memory_mode=memory_mode)
        if any(choice["selected"][key] != placement[key] for key in ("device", "filesystem", "mountpoint", "ephemeral")):
            raise ValueError("The original temporary filesystem changed")
        return choice
    return placement

#!/usr/bin/env python3
"""Observe memory/filesystem capacity; optionally observe one exact allocation."""
from __future__ import annotations

import argparse
import ctypes
import errno
import json
import os
import re
import shutil
import stat
import sys
from copy import deepcopy
from datetime import datetime, timezone
from functools import lru_cache
from pathlib import Path, PurePosixPath

SCHEMA = "commons.worker_capacity/v1"
PROCESS_STATUS_BYTES = 65536
LOCAL_ROOT_FILESYSTEMS = frozenset(("ext2", "ext3", "ext4", "xfs",
                                    "btrfs", "f2fs", "tmpfs", "ramfs"))


def _now():
    return datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")


def _error(exc):
    return {"kind": type(exc).__name__, "errno": getattr(exc, "errno", None)}


def _nonnegative(raw):
    if not re.fullmatch(r"[0-9]+", raw):
        raise ValueError("expected a nonnegative kernel counter")
    return int(raw)


def _host_memory():
    result = {"source": "/proc/meminfo", "total_bytes": None, "available_bytes": None}
    try:
        wanted = {"MemTotal": "total_bytes", "MemAvailable": "available_bytes"}
        for line in Path(result["source"]).read_text(encoding="ascii").splitlines():
            key, _, raw = line.partition(":")
            if key in wanted:
                value, unit = raw.split()
                if unit != "kB":
                    raise ValueError("unexpected memory unit")
                result[wanted[key]] = _nonnegative(value) * 1024
        result["status"] = "ok" if all(result[key] is not None for key in wanted.values()) else "partial"
    except (OSError, UnicodeError, ValueError) as exc:
        result.update(status="unavailable", error=_error(exc))
    return result


def _unescape_mount(value):
    return re.sub(r"\\([0-7]{3})", lambda match: chr(int(match[1], 8)), value)


def _cgroup_location():
    membership = None
    for line in Path("/proc/self/cgroup").read_text(encoding="utf-8").splitlines():
        if line.startswith("0::"):
            membership = PurePosixPath(line[3:])
            break
    if membership is None:
        raise ValueError("no cgroup v2 membership")
    if not membership.is_absolute() or ".." in membership.parts:
        raise ValueError("unresolvable cgroup membership")
    candidates = []
    for line in Path("/proc/self/mountinfo").read_text(encoding="utf-8").splitlines():
        left, separator, right = line.partition(" - ")
        fields = left.split()
        if not separator or not right.startswith("cgroup2 ") or len(fields) < 5:
            continue
        root = PurePosixPath(_unescape_mount(fields[3]))
        mount = Path(_unescape_mount(fields[4]))
        if membership.is_relative_to(root):
            current = mount / str(membership.relative_to(root))
            candidates.append((len(root.parts), str(mount), mount, current))
    if not candidates:
        raise ValueError("no visible cgroup v2 mount matches membership")
    # A subtree mount is more specific than another view of the same hierarchy.
    _, _, mount, current = max(candidates, key=lambda item: item[:2])
    return mount, current, str(membership)


def _pairs(file):
    result = {}
    for line in file.read_text(encoding="ascii").splitlines():
        key, value = line.split()
        if key in result:
            raise ValueError("duplicate kernel counter")
        result[key] = _nonnegative(value)
    return result


def _memory_pressure(file):
    result = {"source": str(file), "status": "unavailable", "some": None, "full": None}
    try:
        rows = {}
        for line in file.read_text(encoding="ascii").splitlines():
            fields = line.split()
            if not fields or fields[0] not in ("some", "full"):
                continue
            kind, *tokens = fields
            if kind in rows:
                raise ValueError("duplicate pressure row")
            values = {}
            for token in tokens:
                key, separator, raw = token.partition("=")
                if not separator or key in values:
                    raise ValueError("invalid pressure field")
                values[key] = raw
            if not {"avg10", "avg60", "avg300", "total"}.issubset(values):
                raise ValueError("missing pressure field")
            row = {}
            for key in ("avg10", "avg60", "avg300"):
                raw = values[key]
                if not re.fullmatch(r"[0-9]+(?:\.[0-9]+)?", raw):
                    raise ValueError("invalid pressure percentage")
                value = float(raw)
                if not 0 <= value <= 100:
                    raise ValueError("pressure percentage out of range")
                row[key + "_percent"] = value
            row["total_us"] = _nonnegative(values["total"])
            rows[kind] = row
        if set(rows) != {"some", "full"}:
            raise ValueError("missing pressure row")
        result.update(status="ok", **rows)
    except (OSError, UnicodeError, ValueError) as exc:
        result["error"] = _error(exc)
    return result


def _cgroup_memory():
    result = {"status": "unavailable", "scope": "visible_cgroup_v2_ancestors",
              "levels": [], "smallest_observed_headroom_bytes": None}
    try:
        mount, current, membership = _cgroup_location()
    except (OSError, UnicodeError, ValueError) as exc:
        result["error"] = _error(exc)
        return result
    result.update(mountpoint=str(mount), membership=membership)
    finite_headrooms = []
    directory = current
    while True:
        row = {"directory": str(directory), "current_bytes": None,
               "max_bytes": None, "max_status": "unavailable",
               "high_bytes": None, "high_status": "unavailable",
               "headroom_bytes": None, "errors": {}}
        for filename, key in (("memory.current", "current"),
                              ("memory.max", "max"), ("memory.high", "high")):
            try:
                raw = (directory / filename).read_text(encoding="ascii").strip()
                if key != "current" and raw == "max":
                    row[key + "_status"] = "unlimited"
                else:
                    row[key + "_bytes"] = _nonnegative(raw)
                    if key != "current":
                        row[key + "_status"] = "finite"
            except (OSError, UnicodeError, ValueError) as exc:
                row["errors"][filename] = _error(exc)
        # Configured protections are context, not an effective reclaim total.
        # Protection behavior is relative to the selected reclaim target.
        protection = {"min_bytes": None, "low_bytes": None, "errors": {}}
        for filename, key in (("memory.min", "min_bytes"), ("memory.low", "low_bytes")):
            try:
                protection[key] = _nonnegative((directory / filename).read_text(encoding="ascii").strip())
            except (OSError, UnicodeError, ValueError) as exc:
                protection["errors"][filename] = _error(exc)
        row["protection"] = protection
        if row["current_bytes"] is not None and row["max_status"] == "finite":
            row["headroom_bytes"] = max(0, row["max_bytes"] - row["current_bytes"])
            row["over_limit_bytes"] = max(0, row["current_bytes"] - row["max_bytes"])
            finite_headrooms.append(row["headroom_bytes"])
        result["levels"].append(row)
        if directory == mount:
            break
        directory = directory.parent
    result["smallest_observed_headroom_bytes"] = min(finite_headrooms) if finite_headrooms else None
    result["status"] = "ok" if all(not row["errors"] for row in result["levels"]) else "partial"
    for filename, key in (("memory.events", "events"), ("memory.stat", "stat_bytes")):
        try:
            values = _pairs(current / filename)
            if key == "stat_bytes":
                values = {name: values[name] for name in
                          ("anon", "file", "shmem", "kernel", "inactive_file", "active_file",
                           "file_mapped", "file_dirty", "file_writeback", "slab",
                           "slab_reclaimable", "slab_unreclaimable") if name in values}
            result[key] = values
        except (OSError, UnicodeError, ValueError) as exc:
            result[key] = None
            result.setdefault("errors", {})[filename] = _error(exc)
            result["status"] = "partial"
    result["pressure"] = _memory_pressure(current / "memory.pressure")
    if result["pressure"]["status"] != "ok":
        result.setdefault("errors", {})["memory.pressure"] = result["pressure"]["error"]
        result["status"] = "partial"
    return result



CURRENT_CGROUP_RECLAIM_MAX_BYTES = 1024 * 1024 * 1024


def _current_reclaim_binding():
    """Bind only this process's visible cgroup; never select an ancestor."""
    mount, current, membership = _cgroup_location()
    if (mount.resolve(strict=True) != mount or current.resolve(strict=True) != current
            or not current.is_relative_to(mount)):
        raise ValueError("The current cgroup mapping contains an unresolved alias")
    directory = current.lstat()
    if not stat.S_ISDIR(directory.st_mode) or current.is_symlink():
        raise ValueError("The current cgroup is not its original directory")
    # cgroup.procs reports PIDs in the reader\'s active PID namespace; the
    # procfs mount may expose another namespace through /proc/self.
    process_id = os.getpid()
    members = {_nonnegative(line.strip())
               for line in (current / "cgroup.procs").read_text(encoding="ascii").splitlines()
               if line.strip()}
    if process_id not in members:
        raise ValueError("This process is absent from the selected current cgroup")
    return {"mountpoint": str(mount), "directory": str(current),
            "membership": membership, "process_id": process_id,
            "mount_namespace": os.readlink("/proc/self/ns/mnt"),
            "cgroup_namespace": os.readlink("/proc/self/ns/cgroup"),
            "directory_device": directory.st_dev, "directory_inode": directory.st_ino}


def reclaim_current_cgroup(requested_bytes, *, expected_cgroup=None):
    """Request reclaim once, then retain fresh observations of the actual result.

    This reuses the original Correspondence current-cgroup proof. It writes only
    memory.reclaim in this process's proved cgroup. Kernel limits and settings
    remain unchanged. A successful write is not a reservation or a guaranteed
    number of freed bytes; EAGAIN may also follow partial reclamation.
    """
    if (type(requested_bytes) is not int
            or not 0 < requested_bytes <= CURRENT_CGROUP_RECLAIM_MAX_BYTES):
        raise ValueError("Current-cgroup reclaim requires 1..1073741824 bytes")
    if expected_cgroup is not None and not isinstance(expected_cgroup, dict):
        raise ValueError("Use the original observed current-cgroup identity")
    result = {"schema": "commons.current-cgroup-reclaim/v1",
              "started_at": _now(), "requested_bytes": requested_bytes,
              "state": "UNAVAILABLE", "request_attempted": False,
              "request_written": False, "written_bytes": None,
              "allocation_guaranteed": False, "current_cgroup_unchanged": None,
              "selection_cgroup_unchanged": None,
              "before": snapshot(include_filesystems=False)}
    descriptor = directory_fd = None
    binding = None
    try:
        if not sys.platform.startswith("linux"):
            raise NotImplementedError("Current-cgroup reclaim requires Linux cgroup v2")
        binding = _current_reclaim_binding()
        result["binding"] = binding
        if expected_cgroup is not None:
            expected = {"mountpoint": expected_cgroup.get("mountpoint"),
                        "membership": expected_cgroup.get("membership"),
                        "directory": (expected_cgroup.get("levels") or [{}])[0].get("directory")}
            result["selection_cgroup_unchanged"] = all(binding[key] == value for key, value in expected.items())
            if not result["selection_cgroup_unchanged"]:
                raise ValueError("The observed current cgroup changed before reclaim")
        directory_fd = os.open(binding["directory"],
            os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
        opened_directory = os.fstat(directory_fd)
        if ((opened_directory.st_dev, opened_directory.st_ino)
                != (binding["directory_device"], binding["directory_inode"])):
            raise ValueError("The opened current cgroup directory changed")
        original = os.stat("memory.reclaim", dir_fd=directory_fd, follow_symlinks=False)
        if not stat.S_ISREG(original.st_mode):
            raise ValueError("The original memory.reclaim entry is not a regular kernel file")
        descriptor = os.open("memory.reclaim",
            os.O_WRONLY | os.O_NOFOLLOW | os.O_CLOEXEC, dir_fd=directory_fd)
        opened = os.fstat(descriptor)
        if ((opened.st_dev, opened.st_ino) != (original.st_dev, original.st_ino)
                or opened.st_dev != opened_directory.st_dev
                or _current_reclaim_binding() != binding):
            raise ValueError("The original current-cgroup binding changed before reclaim")
        result.update(state="SELECTED", file_device=opened.st_dev, file_inode=opened.st_ino)
        command = (str(requested_bytes) + "\n").encode("ascii")
        result["request_attempted"] = True
        written = os.write(descriptor, command)
        result.update(written_bytes=written, request_written=written == len(command),
                      state="RETURNED" if written == len(command) else "SHORT_WRITE")
    except (OSError, UnicodeError, ValueError, RuntimeError, NotImplementedError) as exc:
        result.update(state=("KERNEL_SHORTFALL" if isinstance(exc, OSError)
                             and exc.errno == errno.EAGAIN else "UNAVAILABLE"),
                      error={**_error(exc), "message": str(exc)})
    finally:
        for selected in (descriptor, directory_fd):
            if selected is not None:
                try:
                    os.close(selected)
                except OSError as exc:
                    result.setdefault("close_errors", []).append(_error(exc))
        if binding is not None:
            try:
                after_binding = _current_reclaim_binding()
                result["after_binding"] = after_binding
                result["current_cgroup_unchanged"] = after_binding == binding
            except (OSError, UnicodeError, ValueError, RuntimeError) as exc:
                result["current_cgroup_unchanged"] = False
                result["binding_error"] = {**_error(exc), "message": str(exc)}
        result["after"] = snapshot(include_filesystems=False)
        result["finished_at"] = _now()
    return result


def _filesystem_caller():
    """Read this process's filesystem identity without changing credentials."""
    result = {"effective_uid": None, "filesystem_uid": None,
              "mapped_parent_uid": None, "uid_mapping": None, "status": "unavailable",
              "effective_capabilities_hex": None, "cap_sys_resource_effective": None,
              "user_namespace": None}
    if not sys.platform.startswith("linux") or not hasattr(os, "geteuid"):
        return result
    result["effective_uid"] = os.geteuid()
    try:
        with Path("/proc/self/status").open("r", encoding="ascii") as source:
            raw = source.read(PROCESS_STATUS_BYTES + 1)
        if len(raw) > PROCESS_STATUS_BYTES:
            raise ValueError("process identity exceeds read bound")
        rows = [line.split()[1:] for line in raw.splitlines() if line.startswith("Uid:")]
        if len(rows) != 1 or len(rows[0]) != 4:
            raise ValueError("missing or invalid process UID row")
        real, effective, saved, filesystem = map(_nonnegative, rows[0])
        if effective != result["effective_uid"]:
            raise ValueError("process identity changed during observation")
        result["filesystem_uid"] = filesystem
        capability_rows = [line.split()[1:] for line in raw.splitlines()
                           if line.startswith("CapEff:")]
        if (len(capability_rows) != 1 or len(capability_rows[0]) != 1
                or not re.fullmatch(r"[0-9a-fA-F]{1,16}", capability_rows[0][0])):
            raise ValueError("missing or invalid effective capability row")
        capabilities = capability_rows[0][0].lower()
        result.update(effective_capabilities_hex=capabilities,
                      cap_sys_resource_effective=bool(int(capabilities, 16) & (1 << 24)),
                      user_namespace=os.readlink("/proc/self/ns/user"))
        with Path("/proc/self/uid_map").open("r", encoding="ascii") as source:
            raw = source.read(4097)
        if len(raw) > 4096:
            raise ValueError("UID mapping exceeds read bound")
        matches = []
        for line in raw.splitlines():
            inside, parent, count = map(_nonnegative, line.split())
            if count == 0:
                raise ValueError("empty UID mapping range")
            if inside <= filesystem < inside + count:
                matches.append((inside, parent, count))
        if len(matches) != 1:
            raise ValueError("filesystem UID has no unique visible mapping")
        inside, parent, count = matches[0]
        result.update(mapped_parent_uid=parent + filesystem - inside,
                      uid_mapping={"inside_uid": inside, "parent_uid": parent, "count": count},
                      status="ok")
    except (OSError, UnicodeError, ValueError) as exc:
        result["error"] = _error(exc)
    return result


@lru_cache(maxsize=1)
def _mount_topology(raw):
    """Reuse parsing only when freshly read mountinfo bytes are identical."""
    mounts = []
    for line in raw.splitlines():
        left, separator, right = line.partition(" - ")
        fields, filesystem = left.split(), right.split()
        if separator and len(fields) >= 6 and len(filesystem) >= 3:
            mount = Path(_unescape_mount(fields[4]))
            options = set(fields[5].split(",")) | set(filesystem[2].split(","))
            reserved_user = tuple(item.partition("=")[2] for item in options
                                  if item.startswith("resuid="))
            mounts.append((len(mount.parts), str(mount), filesystem[0],
                           "ro" in options, reserved_user))
    return tuple(mounts)


def _filesystem_context(*, namespace=False):
    """Fresh metadata for one observation; no capacity or path cache."""
    value = {"caller": _filesystem_caller(), "mountinfo": None, "mounts": (),
             "mount_namespace": None, "mount_error": None}
    try:
        raw = Path("/proc/self/mountinfo").read_text(encoding="utf-8")
        value.update(mountinfo=raw, mounts=_mount_topology(raw))
        if namespace:
            value["mount_namespace"] = os.readlink("/proc/self/ns/mnt")
    except (OSError, UnicodeError, ValueError) as exc:
        value["mount_error"] = _error(exc)
    return value


def _filesystem(value, *, nearest_existing=False, context=None):
    result = {"requested_path": value, "available_bytes": None,
              "total_bytes": None, "inodes_available": None, "inodes_total": None}
    try:
        path = Path(value).expanduser().resolve(strict=not nearest_existing)
        observed = path
        if nearest_existing:
            while not observed.exists() and observed != observed.parent:
                observed = observed.parent
        selected = observed.stat()
        stat = os.statvfs(observed) if hasattr(os, "statvfs") else None
        if stat is not None:
            unit = stat.f_frsize or stat.f_bsize
            available, total = stat.f_bavail * unit, stat.f_blocks * unit
            source = "statvfs_f_bavail"
        else:
            usage = shutil.disk_usage(observed)
            available, total, source = usage.free, usage.total, "shutil.disk_usage"
        result.update(path=str(path), observed_path=str(observed),
                      requested_path_exists=path.exists(), device=selected.st_dev, status="ok",
                      available_bytes=available, total_bytes=total,
                      available_bytes_source=source)
        context = _filesystem_context() if context is None else context
        mounts = [row for row in context["mounts"] if observed.is_relative_to(Path(row[1]))]
        if mounts:
            _, mount, filesystem, read_only, reserved_user = max(mounts, key=lambda item: item[:2])
            result.update(mountpoint=mount, filesystem=filesystem,
                          memory_backed=filesystem in ("tmpfs", "ramfs"),
                          mount_read_only=read_only)
            if reserved_user:
                result["reserved_user_is_root"] = all(value == "0" for value in reserved_user)
        if context["mount_error"] is not None:
            result["mount_error"] = deepcopy(context["mount_error"])
        if stat is not None:
            caller = deepcopy(context["caller"])
            read_only = bool(stat.f_flag & getattr(os, "ST_RDONLY", 1)) or result.get("mount_read_only", False)
            local_root = (caller["status"] == "ok" and caller["effective_uid"] == 0
                          and caller["filesystem_uid"] == 0 and caller["mapped_parent_uid"] == 0
                          and result.get("filesystem") in LOCAL_ROOT_FILESYSTEMS
                          and result.get("mount_read_only") is False
                          and result.get("reserved_user_is_root", True) and not read_only)
            result.update(total_bytes=stat.f_blocks * unit, inodes_total=stat.f_files,
                          free_including_reserved_bytes=stat.f_bfree * unit,
                          unprivileged_available_bytes=stat.f_bavail * unit,
                          inodes_free_including_reserved=stat.f_ffree,
                          inodes_unprivileged_available=stat.f_favail,
                          caller_identity=caller, read_only=read_only)
            # OverlayFS forwards underlying operations using stashed mount
            # credentials. The visible caller's root UID, capabilities and UID
            # mapping do not establish access to the backing mount's reserves.
            # Keep both observations; only direct qualified local filesystems
            # retain the original root estimate. Neither estimate guarantees a
            # later allocation against quotas or concurrent writers.
            reserve_basis = ("overlay_backing_credentials_unobserved"
                             if result.get("filesystem") == "overlay"
                             else "qualified_direct_local_root_estimate" if local_root
                             else "unprivileged_available_counter")
            result.update(reserved_space_estimate_basis=reserve_basis,
                          allocation_guaranteed=False,
                          reserved_space_bytes=max(0, (stat.f_bfree - stat.f_bavail) * unit))
            if read_only:
                result.update(available_bytes=0, inodes_available=0,
                              available_bytes_source="read_only",
                              inodes_available_source="read_only")
            elif local_root:
                result.update(available_bytes=stat.f_bfree * unit, inodes_available=stat.f_ffree,
                              available_bytes_source="statvfs_f_bfree_local_root",
                              inodes_available_source="statvfs_f_ffree_local_root")
            else:
                result.update(available_bytes=stat.f_bavail * unit, inodes_available=stat.f_favail,
                              available_bytes_source="statvfs_f_bavail",
                              inodes_available_source="statvfs_f_favail")
        else:
            result["inode_status"] = "unavailable"
    except (OSError, ValueError, RuntimeError) as exc:
        result.update(status="error", error=_error(exc))
    return result


def _filesystem_observations(paths, *, nearest_existing=False):
    """Share one checked metadata frame while every path gets fresh counters."""
    values = [str(value) for value in paths]
    if len(values) < 2:
        return [_filesystem(value, nearest_existing=nearest_existing) for value in values]
    context = _filesystem_context(namespace=True)
    shareable = (context["mountinfo"] is not None and context["mount_namespace"] is not None
                 and context["mount_error"] is None and context["caller"].get("status") == "ok")
    if shareable:
        rows = [_filesystem(value, nearest_existing=nearest_existing, context=context)
                for value in values]
        # setns, changed credentials or a changed mount table cannot make a
        # borrowed classification authoritative. Fall back to fresh original
        # per-path reads for this sample when the metadata frame changed.
        if _filesystem_context(namespace=True) == context:
            return rows
    return [_filesystem(value, nearest_existing=nearest_existing) for value in values]


def _allocation_writer():
    """Bind an allocation to the current filesystem and namespace identity."""
    caller = _filesystem_caller()
    for name in ("mnt", "pid"):
        caller[name + "_namespace"] = os.readlink("/proc/self/ns/" + name)
    return caller


def _linux_fallocate(descriptor, amount):
    # The POSIX libc wrapper may emulate allocation by writing zeros on an
    # unsupported filesystem. Admission needs the actual Linux allocation call.
    library = ctypes.CDLL(None, use_errno=True)
    operation = library.fallocate
    operation.argtypes = (ctypes.c_int, ctypes.c_int, ctypes.c_longlong, ctypes.c_longlong)
    operation.restype = ctypes.c_int
    if operation(descriptor, 0, 0, amount):
        code = ctypes.get_errno()
        raise OSError(code, os.strerror(code))


def allocation_probe(value, required_bytes, *, nearest_existing=True, expected_device=None,
                     retained=None, expected_writer=None):
    """Allocate the exact requested extent through the original writer.

    By default the anonymous extent is released before return, preserving the
    explicit observer/placement API. Native admission may supply its outer
    ExitStack: the returned extent then survives until its ledger claim commits.
    The returned observation records the actual release when that stack closes.
    """
    if type(required_bytes) is not int or not 0 < required_bytes <= (1 << 63) - 1:
        raise ValueError("Allocation bytes must be a positive signed 64-bit integer")
    if retained is not None and not callable(getattr(retained, "callback", None)):
        raise ValueError("Retained allocation requires a caller-owned ExitStack")
    result = {"requested_path": str(value), "requested_bytes": required_bytes,
              "source": "linux_fallocate_anonymous_file", "started_at": _now(),
              "status": "error", "allocation_released": False,
              "allocation_guaranteed_after_release": False}
    directory = descriptor = None

    def release():
        nonlocal directory, descriptor
        if descriptor is not None:
            selected, descriptor = descriptor, None
            try:
                os.close(selected)
                result["allocation_released"] = True
                result["released_at"] = _now()
            except OSError as exc:
                result.update(status="error", release_error=_error(exc))
        if directory is not None:
            selected, directory = directory, None
            try:
                os.close(selected)
            except OSError as exc:
                result.update(status="error", directory_close_error=_error(exc))

    try:
        if (not sys.platform.startswith("linux") or ctypes.sizeof(ctypes.c_long) != 8
                or not hasattr(os, "O_TMPFILE")):
            raise NotImplementedError("Native anonymous Linux allocation is unavailable")
        writer = _allocation_writer()
        if writer.get("status") != "ok" or (expected_writer is not None and writer != expected_writer):
            raise ValueError("Allocation writer differs from the observed native writer")
        supplied = Path(value).expanduser()
        original = supplied.resolve(strict=not nearest_existing)
        path = original
        while nearest_existing and not path.exists() and path != path.parent:
            path = path.parent
        if path.is_file():
            path = path.parent
        directory = os.open(path, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
        parent = os.fstat(directory)
        if expected_device is not None and parent.st_dev != expected_device:
            raise ValueError("Allocation directory moved to a different filesystem")
        result.update(allocation_directory=str(path), device=parent.st_dev,
                      directory_inode=parent.st_ino, writer=writer)
        before = os.fstatvfs(directory)
        if before.f_flag & getattr(os, "ST_RDONLY", 1):
            raise OSError(errno.EROFS, "Allocation filesystem is read-only")
        unit = before.f_frsize or before.f_bsize
        result.update(counter_available_bytes=before.f_bavail * unit,
                      physical_free_bytes=before.f_bfree * unit)
        descriptor = os.open(".", os.O_TMPFILE | os.O_EXCL | os.O_RDWR | os.O_CLOEXEC,
                             0o600, dir_fd=directory)
        _linux_fallocate(descriptor, required_bytes)
        os.fsync(descriptor)
        allocated = os.fstat(descriptor)
        current = os.stat(path, follow_symlinks=False)
        if ((current.st_dev, current.st_ino) != (parent.st_dev, parent.st_ino)
                or supplied.resolve(strict=not nearest_existing) != original
                or allocated.st_dev != parent.st_dev or allocated.st_size != required_bytes
                or allocated.st_nlink != 0 or allocated.st_blocks * 512 < required_bytes
                or _allocation_writer() != writer):
            raise ValueError("Anonymous allocation writer, directory or extent changed")
        if os.fstatvfs(directory).f_flag & getattr(os, "ST_RDONLY", 1):
            raise OSError(errno.EROFS, "Allocation filesystem became read-only")
        result.update(status="ok", allocated_extent_bytes=required_bytes,
                      allocated_blocks_bytes=allocated.st_blocks * 512)
        if retained is not None:
            retained.callback(release)
    except (OSError, ValueError, RuntimeError, NotImplementedError, AttributeError) as exc:
        result.update(status="error", error={**_error(exc), "message": str(exc)})
    finally:
        if retained is None or result["status"] != "ok":
            release()
        result["finished_at"] = _now()
    return result


def snapshot(paths=None, *, nearest_existing=False, process_rss=False,
             max_processes=256, max_process_bytes=1048576, storage_roots=None,
             process_storage=False, storage_sample_seconds=0,
             include_memory=True, include_filesystems=True):
    """Observe capacity for an existing caller without creating directories.

    Filesystem aliases share the returned device and are never summed. A future
    output path can observe its existing ancestor explicitly; memory-backed
    storage still consumes the separately observed cgroup/host memory budget.
    """
    if type(include_memory) is not bool or type(include_filesystems) is not bool:
        raise ValueError("Capacity observation scope requires explicit booleans")
    report = {"schema": SCHEMA, "started_at": _now()}
    if include_memory:
        report.update(host_memory=_host_memory(), cgroup_memory=_cgroup_memory())
    if include_filesystems:
        report["filesystems"] = _filesystem_observations(paths or ["."],
            nearest_existing=nearest_existing)
    if process_rss:
        report["process_rss"] = _process_rss(max_processes, max_process_bytes)
    if storage_roots or process_storage or storage_sample_seconds:
        if __package__:
            from .worker_storage import storage_consumers
        else:
            from worker_storage import storage_consumers
        try:
            report["storage_consumers"] = storage_consumers(storage_roots or paths or ["."],
                include_processes=process_storage, sample_seconds=storage_sample_seconds)
        except (OSError, ValueError) as exc:
            report["storage_consumers"] = {"status": "error", "error": _error(exc), "message": str(exc)}
    report["finished_at"] = _now()
    return report


def _process_row(raw, expected_pid):
    fields = {}
    for line in raw.splitlines():
        key, separator, value = line.partition(b":")
        if separator and key in (b"Name", b"Pid", b"PPid", b"VmRSS"):
            if key in fields:
                raise ValueError("duplicate process status field")
            fields[key] = value
    if not {b"Name", b"Pid", b"PPid"}.issubset(fields):
        raise ValueError("missing process status field")
    pid = _nonnegative(fields[b"Pid"].strip().decode("ascii"))
    parent_pid = _nonnegative(fields[b"PPid"].strip().decode("ascii"))
    if pid != expected_pid:
        raise ValueError("process status PID differs from directory")
    name = fields[b"Name"]
    name = name[1:] if name.startswith(b"\t") else name.lstrip(b" ")
    rss = None
    if b"VmRSS" in fields:
        value, unit = fields[b"VmRSS"].decode("ascii").split()
        if unit != "kB":
            raise ValueError("unexpected process RSS unit")
        rss = _nonnegative(value) * 1024
    return {"pid": pid, "parent_pid": parent_pid,
            "name": name.decode("utf-8", errors="backslashreplace"), "rss_bytes": rss}


def _process_rss(max_processes, max_status_bytes):
    coverage = {"max_processes": max_processes, "max_status_bytes": max_status_bytes,
                "max_bytes_per_status": PROCESS_STATUS_BYTES,
                "max_directory_entries": max_processes + 1024,
                "directory_entries_seen": 0, "pid_entries_seen": 0,
                "status_files_attempted": 0, "status_bytes_read": 0,
                "processes_returned": 0, "processes_with_rss": 0,
                "enumeration_complete": False, "stop_reason": None,
                "pending_pid": None, "unavailable_status_files": [],
                "truncated_status_files": [], "missing_rss_pids": []}
    result = {"source": "/proc/[pid]/status", "scope": "visible_procfs_processes",
              "status": "unavailable", "processes": [], "rss_sum_bytes": None,
              "coverage": coverage}
    try:
        with os.scandir("/proc") as entries:
            while coverage["directory_entries_seen"] < coverage["max_directory_entries"]:
                try:
                    entry = next(entries)
                except StopIteration:
                    coverage["enumeration_complete"] = True
                    break
                coverage["directory_entries_seen"] += 1
                if not entry.name.isascii() or not entry.name.isdecimal():
                    continue
                pid = int(entry.name)
                coverage["pid_entries_seen"] += 1
                if coverage["status_files_attempted"] >= max_processes:
                    coverage.update(stop_reason="process_limit", pending_pid=pid)
                    break
                remaining = max_status_bytes - coverage["status_bytes_read"]
                if remaining == 0:
                    coverage.update(stop_reason="total_byte_limit", pending_pid=pid)
                    break
                allowance = min(PROCESS_STATUS_BYTES, remaining)
                raw = bytearray()
                complete = False
                coverage["status_files_attempted"] += 1
                try:
                    with open(entry.path + "/status", "rb", buffering=0) as stream:
                        while len(raw) < allowance:
                            chunk = stream.read(min(8192, allowance - len(raw)))
                            if not chunk:
                                complete = True
                                break
                            raw.extend(chunk)
                            coverage["status_bytes_read"] += len(chunk)
                except OSError as exc:
                    coverage["unavailable_status_files"].append({"pid": pid, "error": _error(exc)})
                    continue
                if not complete:
                    reason = "total_byte_limit" if coverage["status_bytes_read"] == max_status_bytes else "per_status_byte_limit"
                    coverage["truncated_status_files"].append({"pid": pid, "reason": reason,
                                                              "bytes_read": len(raw)})
                    if reason == "total_byte_limit":
                        coverage["stop_reason"] = reason
                        break
                    continue
                try:
                    row = _process_row(bytes(raw), pid)
                except (UnicodeError, ValueError) as exc:
                    coverage["unavailable_status_files"].append({"pid": pid, "error": _error(exc)})
                    continue
                result["processes"].append(row)
                if row["rss_bytes"] is None:
                    coverage["missing_rss_pids"].append(pid)
            else:
                coverage["stop_reason"] = "directory_entry_limit"
    except OSError as exc:
        result["error"] = _error(exc)
        coverage["stop_reason"] = "directory_read_error"
    rows = result["processes"]
    rows.sort(key=lambda row: (row["rss_bytes"] is None, -(row["rss_bytes"] or 0), row["pid"]))
    coverage["processes_returned"] = len(rows)
    known = [row["rss_bytes"] for row in rows if row["rss_bytes"] is not None]
    coverage["processes_with_rss"] = len(known)
    result["rss_sum_bytes"] = sum(known) if known else None
    if "error" not in result or coverage["status_files_attempted"]:
        result["status"] = "ok" if (coverage["enumeration_complete"]
            and not coverage["unavailable_status_files"]
            and not coverage["truncated_status_files"]
            and not coverage["missing_rss_pids"]) else "partial"
    return result


def _positive_limit(maximum):
    def parse(raw):
        try:
            value = _nonnegative(raw)
        except ValueError as exc:
            raise argparse.ArgumentTypeError("expected an integer from 1 to " + str(maximum)) from exc
        if not 1 <= value <= maximum:
            raise argparse.ArgumentTypeError("expected an integer from 1 to " + str(maximum))
        return value
    return parse


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--path", action="append", help="existing file/directory; repeat for each output filesystem (default: current directory)")
    parser.add_argument("--scope", choices=("all", "memory", "filesystems"), default="all",
                        help="read all capacity by default, or only the selected resource fields")
    parser.add_argument("--allocation-probe", action="append", default=[], metavar="PATH=MIB",
                        help="explicitly allocate and release this exact positive whole-MiB extent; repeat per destination")
    parser.add_argument("--reclaim-current-cgroup", type=_positive_limit(1024), metavar="MIB",
                        help="explicitly request one current-cgroup reclaim of 1..1024 MiB; retain actual before/after counters")
    parser.add_argument("--process-rss", action="store_true", help="include a bounded read of visible process PID, parent, short name and RSS")
    parser.add_argument("--max-processes", type=_positive_limit(4096), default=256,
                        help="status-file attempts with --process-rss (1..4096; default: 256)")
    parser.add_argument("--max-process-bytes", type=_positive_limit(8388608), default=1048576,
                        help="total status bytes with --process-rss (1..8388608; default: 1048576)")
    parser.add_argument("--storage-root", action="append",
                        help="walk metadata beneath this directory and report per-child allocated bytes; repeat for independent roots")
    parser.add_argument("--process-storage", action="store_true",
                        help="include matching live process cwd/open-file metadata for selected storage roots")
    parser.add_argument("--storage-sample-seconds", type=float, default=0,
                        help="sample matching process writes and filesystem changes for 0..30 seconds")
    args = parser.parse_args(argv)
    report = snapshot(args.path, process_rss=args.process_rss,
                      max_processes=args.max_processes, max_process_bytes=args.max_process_bytes,
                      storage_roots=args.storage_root, process_storage=args.process_storage,
                      storage_sample_seconds=args.storage_sample_seconds,
                      include_memory=args.scope != "filesystems",
                      include_filesystems=args.scope != "memory")
    if args.reclaim_current_cgroup is not None:
        report["current_cgroup_reclaim"] = reclaim_current_cgroup(args.reclaim_current_cgroup * 1024 * 1024)
    if args.allocation_probe:
        probes = []
        for declaration in args.allocation_probe:
            path, separator, amount = declaration.rpartition("=")
            if not separator or not path or not re.fullmatch(r"[0-9]+", amount) or int(amount) <= 0:
                parser.error("--allocation-probe requires PATH=positive-whole-MIB")
            probes.append(allocation_probe(path, int(amount) * 1024 * 1024))
        report["allocation_probes"] = probes
    print(json.dumps(report, indent=2, ensure_ascii=True, allow_nan=False))
    return 2 if (any(row["status"] == "error" for row in report.get("filesystems", []))
        or report.get("storage_consumers", {}).get("status") == "error"
        or any(row["status"] != "ok" for row in report.get("allocation_probes", []))
        or (args.reclaim_current_cgroup is not None
            and (report["current_cgroup_reclaim"]["state"] != "RETURNED"
                 or report["current_cgroup_reclaim"]["current_cgroup_unchanged"] is not True))) else 0


if __name__ == "__main__":
    sys.exit(main())

"""Metadata-only storage consumers for the existing worker capacity operator.

Selected roots are explicit. Directory walks use held directory descriptors and
do not follow links or cross mounts. Process observations read procfs metadata,
not arguments, environment or file contents. No data is deleted and no process
is signalled by this module.
"""
from __future__ import annotations

from collections import defaultdict
from contextlib import contextmanager
from datetime import datetime, timezone
import math
import os
from pathlib import Path
import stat
import time

_DIRECTORY = os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW
_PATH_DIRECTORY = getattr(os, "O_PATH", os.O_RDONLY) | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW


def _now():
    return datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")


def _error(exc):
    return {"kind": type(exc).__name__, "errno": getattr(exc, "errno", None)}


def _inode(metadata):
    return metadata.st_dev, metadata.st_ino


def _read(path, maximum=65536):
    with Path(path).open("r", encoding="utf-8", errors="backslashreplace") as stream:
        value = stream.read(maximum + 1)
    if len(value) > maximum:
        raise ValueError("Procfs metadata exceeds its read bound")
    return value


def _fd_mount(descriptor):
    fields = {}
    for line in _read(Path("/proc/self/fdinfo") / str(descriptor), 4096).splitlines():
        key, separator, value = line.partition(":")
        if separator and key in ("mnt_id", "ino"):
            if key in fields or not value.strip().isdecimal():
                raise ValueError("File descriptor mount metadata is invalid")
            fields[key] = int(value.strip())
    if "mnt_id" not in fields:
        raise ValueError("File descriptor mount identity is unavailable")
    actual = os.fstat(descriptor)
    if fields.get("ino", actual.st_ino) != actual.st_ino:
        raise ValueError("File descriptor inode changed during observation")
    return fields["mnt_id"]


def _optional_mount(descriptor):
    try:
        return _fd_mount(descriptor), None
    except (OSError, ValueError) as exc:
        return None, _error(exc)


def _owner(path, roots):
    matches = [root for root in roots if path.is_relative_to(root)]
    if not matches:
        return None
    root = max(matches, key=lambda value: len(value.parts))
    relative = path.relative_to(root)
    return str(root / relative.parts[0]) if relative.parts else str(root)


@contextmanager
def _selected_roots(roots):
    selected = []
    try:
        for path in roots:
            path = Path(path)
            before = path.lstat()
            descriptor = os.open(path, _DIRECTORY)
            try:
                opened = os.fstat(descriptor)
                if not stat.S_ISDIR(before.st_mode) or _inode(before) != _inode(opened):
                    raise ValueError("Selected storage root changed while opening")
                mount, mount_error = _optional_mount(descriptor)
                selected.append({"path": path, "fd": descriptor,
                    "device": opened.st_dev, "inode": opened.st_ino,
                    "mount_id": mount, "mount_error": mount_error})
            except BaseException:
                os.close(descriptor)
                raise
        yield selected
    finally:
        for root in selected:
            os.close(root["fd"])


def _public_root(root):
    return {key: str(value) if key == "path" else value
            for key, value in root.items() if key != "fd"}


def _root_changes(roots):
    changes = []
    for root in roots:
        try:
            before = root["path"].lstat()
            descriptor = os.open(root["path"], _PATH_DIRECTORY)
            try:
                current = os.fstat(descriptor)
                mount, error = _optional_mount(descriptor)
            finally:
                os.close(descriptor)
            if (not stat.S_ISDIR(before.st_mode)
                    or _inode(before) != _inode(current)
                    or _inode(current) != (root["device"], root["inode"])
                    or (root["mount_id"] is not None and mount != root["mount_id"])):
                changes.append({"path": str(root["path"]), "status": "root_changed",
                    "selected": _public_root(root),
                    "current": {"device": current.st_dev, "inode": current.st_ino,
                                "mount_id": mount, "mount_error": error}})
        except (OSError, ValueError) as exc:
            changes.append({"path": str(root["path"]), "status": "root_unavailable",
                            "error": _error(exc)})
    return changes


def _directory_consumers(roots):
    seen, walked, rows, errors = set(), set(), {}, []
    started = _now()
    paths = [root["path"] for root in roots]

    def error(path, row, exc):
        row["errors"] += 1
        if len(errors) < 50:
            errors.append({"path": str(path), **_error(exc)})

    def row_for(path):
        owner = _owner(path, paths)
        return rows.setdefault(owner, {"path": owner, "logical_bytes": 0,
            "allocated_bytes": 0, "regular_files": 0, "directories": 0,
            "symbolic_links": 0, "shared_inode_entries": 0,
            "other_entries": 0, "mounts_skipped": 0, "errors": 0})

    def count(path, metadata, root):
        row = row_for(path)
        identity = _inode(metadata)
        if metadata.st_dev != root["device"]:
            row["mounts_skipped"] += 1
            return row
        if identity in seen:
            row["shared_inode_entries"] += 1
            return row
        seen.add(identity)
        row["allocated_bytes"] += getattr(metadata, "st_blocks", 0) * 512
        if stat.S_ISLNK(metadata.st_mode):
            row["symbolic_links"] += 1
        elif stat.S_ISDIR(metadata.st_mode):
            row["directories"] += 1
        elif stat.S_ISREG(metadata.st_mode):
            row["regular_files"] += 1
            row["logical_bytes"] += metadata.st_size
        else:
            row["other_entries"] += 1
        return row

    def walk_key(metadata, root):
        # Aliased inodes share allocation, but separately selected mount views
        # may expose different descendants. Traverse each held mount once.
        return metadata.st_dev, metadata.st_ino, root["mount_id"]

    for root in roots:
        stack = []
        try:
            metadata = os.fstat(root["fd"])
            row = count(root["path"], metadata, root)
            key = walk_key(metadata, root)
            if key in walked:
                continue
            descriptor = os.dup(root["fd"])
            try:
                iterator = os.scandir(descriptor)
            except BaseException:
                os.close(descriptor)
                raise
            walked.add(key)
            stack.append((descriptor, iterator, root["path"]))
            while stack:
                parent_fd, iterator, parent_path = stack[-1]
                try:
                    entry = next(iterator)
                except StopIteration:
                    iterator.close()
                    os.close(parent_fd)
                    stack.pop()
                    continue
                path = parent_path / entry.name
                try:
                    metadata = os.stat(entry.name, dir_fd=parent_fd, follow_symlinks=False)
                except OSError as exc:
                    error(path, row_for(path), exc)
                    continue
                if not stat.S_ISDIR(metadata.st_mode) or metadata.st_dev != root["device"]:
                    count(path, metadata, root)
                    continue
                child = None
                row = row_for(path)
                try:
                    child = os.open(entry.name, _DIRECTORY, dir_fd=parent_fd)
                    held = os.fstat(child)
                    if _inode(held) != _inode(metadata):
                        raise ValueError("Directory changed while opening")
                    # Reject an unselected mount before it enters the inode
                    # accounting set or prevents a later explicit-root walk.
                    if root["mount_id"] is not None and _fd_mount(child) != root["mount_id"]:
                        row["mounts_skipped"] += 1
                        continue
                    count(path, held, root)
                    key = walk_key(held, root)
                    if key in walked:
                        continue
                    child_iterator = os.scandir(child)
                    walked.add(key)
                    stack.append((child, child_iterator, path))
                    child = None
                except (OSError, ValueError) as exc:
                    error(path, row, exc)
                finally:
                    if child is not None:
                        os.close(child)
        except (OSError, ValueError) as exc:
            error(root["path"], row_for(root["path"]), exc)
        finally:
            for descriptor, iterator, path in reversed(stack):
                iterator.close()
                os.close(descriptor)
    result = sorted(rows.values(), key=lambda item: (-item["allocated_bytes"], item["path"]))
    return {"started_at": started, "finished_at": _now(), "consumers": result,
        "unique_allocated_bytes": sum(item["allocated_bytes"] for item in result),
        "unique_logical_bytes": sum(item["logical_bytes"] for item in result),
        "status": "partial" if errors else "ok", "errors": errors,
        "accounting": "st_blocks * 512; each device/inode counted once across held selected roots; symbolic links are not followed",
        "mount_boundary": "mount ID and device when procfs fdinfo is readable; device otherwise"}


def directory_consumers(roots):
    """Read allocation once per inode across the selected directory union."""
    with _selected_roots(roots) as selected:
        result = _directory_consumers(selected)
        result["root_changes"] = _root_changes(selected)
        if result["root_changes"]:
            result["status"] = "partial"
        return result


def _process_identity(directory):
    raw = _read(directory / "stat")
    end = raw.rfind(")")
    fields = raw[end + 2:].split()
    pid = int(raw.split(" ", 1)[0])
    if end < 0 or len(fields) < 20 or not fields[19].isdecimal():
        raise ValueError("Original process identity is incomplete")
    return {"proc_pid": pid, "start_ticks": fields[19],
        "name": raw[raw.find("(") + 1:end], "parent_proc_pid": int(fields[1]),
        "pid_namespace": os.readlink(directory / "ns/pid"),
        "mount_namespace": os.readlink(directory / "ns/mnt")}


def _same_process(before, after):
    return all(before[key] == after[key] for key in
               ("proc_pid", "start_ticks", "pid_namespace", "mount_namespace"))


def _io(directory):
    fields = {}
    for line in _read(directory / "io").splitlines():
        key, _, value = line.partition(":")
        if key in {"read_bytes", "write_bytes", "cancelled_write_bytes", "syscw"}:
            if key in fields or not value.strip().isdecimal():
                raise ValueError("Process I/O counters are invalid")
            fields[key] = int(value.strip())
    return fields


def _root_for(path, roots):
    return max((root for root in roots if path.is_relative_to(root["path"])),
               key=lambda root: len(root["path"].parts), default=None)


def _open_descendant(directory_fd, parts):
    descriptor = os.dup(directory_fd)
    try:
        for part in parts:
            next_descriptor = os.open(part, _PATH_DIRECTORY, dir_fd=descriptor)
            os.close(descriptor)
            descriptor = next_descriptor
        return descriptor
    except BaseException:
        os.close(descriptor)
        raise


def _process_root(directory, root):
    """Compare the selected directory in the process's own filesystem view."""
    descriptor = os.open(directory / "root",
        getattr(os, "O_PATH", os.O_RDONLY) | os.O_DIRECTORY | os.O_CLOEXEC)
    try:
        selected = _open_descendant(descriptor, root["path"].parts[1:])
    finally:
        os.close(descriptor)
    try:
        metadata = os.fstat(selected)
        if _inode(metadata) != (root["device"], root["inode"]):
            return {"status": "different_root", "device": metadata.st_dev,
                    "inode": metadata.st_ino}
        return {"status": "same_root", "device": metadata.st_dev,
                "inode": metadata.st_ino, "mount_id": _fd_mount(selected)}
    finally:
        os.close(selected)


def _named_identity(root, path):
    relative = path.relative_to(root["path"])
    if not relative.parts:
        return root["device"], root["inode"]
    descriptor = _open_descendant(root["fd"], relative.parts[:-1])
    try:
        metadata = os.stat(relative.parts[-1], dir_fd=descriptor, follow_symlinks=False)
        if stat.S_ISLNK(metadata.st_mode):
            raise ValueError("Selected path became a symbolic link")
        return _inode(metadata)
    finally:
        os.close(descriptor)


def _path_evidence(path, metadata, mount_id, root, process_root):
    if process_root["status"] != "same_root":
        return None
    if metadata.st_nlink == 0:
        # No current directory entry can prove an unlinked file's old parent.
        # Keep this weaker, explicit evidence separate from exact live paths.
        if metadata.st_dev != root["device"] or mount_id != process_root["mount_id"]:
            return None
        return "unlinked_path_in_matching_root_mount"
    if _named_identity(root, path) != _inode(metadata):
        return None
    return "same_live_path_inode"


def _process_consumers(roots):
    rows, files, errors, excluded = [], {}, defaultdict(int), defaultdict(int)
    inspected = 0
    observer = {}
    try:
        observer = {**_process_identity(Path("/proc/self")),
                    "boot_id": _read("/proc/sys/kernel/random/boot_id", 256).strip()}
    except (OSError, ValueError, IndexError) as exc:
        observer["error"] = _error(exc)
        errors["observer_" + type(exc).__name__] += 1
    try:
        with os.scandir("/proc") as entries:
            directories = [Path(entry.path) for entry in entries
                if entry.name.isascii() and entry.name.isdecimal()]
    except OSError as exc:
        return {"status": "unavailable", "processes": [], "open_files": [],
                "observer": observer, "error": _error(exc)}
    for original in directories:
        inspected += 1
        process_fd = None
        candidates, root_views = [], {}
        try:
            # Relative reads through this held proc directory cannot switch to a
            # new process merely because the numeric PID was reused.
            process_fd = os.open(original, _DIRECTORY)
            directory = Path("/proc/self/fd") / str(process_fd)
            identity = _process_identity(directory)
            if identity["proc_pid"] != int(original.name):
                raise ValueError("Process directory identity differs")

            def view(root):
                key = str(root["path"])
                if key not in root_views:
                    root_views[key] = _process_root(directory, root)
                return root_views[key]

            cwd, cwd_owner, cwd_evidence = None, None, None
            try:
                target = os.readlink(directory / "cwd")
                descriptor = os.open(directory / "cwd",
                    getattr(os, "O_PATH", os.O_RDONLY) | os.O_DIRECTORY | os.O_CLOEXEC)
                try:
                    metadata, mount_id = os.fstat(descriptor), _fd_mount(descriptor)
                    clean = target.removesuffix(" (deleted)") if metadata.st_nlink == 0 else target
                    path = Path(clean)
                    root = _root_for(path, roots) if path.is_absolute() else None
                    if root and os.readlink(directory / "cwd") == target:
                        evidence = _path_evidence(path, metadata, mount_id, root, view(root))
                        if evidence:
                            cwd, cwd_owner, cwd_evidence = clean, _owner(path, [root["path"]]), evidence
                        else:
                            excluded["cwd_root_or_inode_mismatch"] += 1
                finally:
                    os.close(descriptor)
            except (OSError, ValueError) as exc:
                errors["cwd_" + type(exc).__name__] += 1

            try:
                with os.scandir(directory / "fd") as descriptors:
                    for entry in descriptors:
                        pinned = None
                        try:
                            location = directory / "fd" / entry.name
                            target = os.readlink(location)
                            if not target.startswith("/"):
                                continue
                            metadata = os.stat(location)
                            if not stat.S_ISREG(metadata.st_mode):
                                continue
                            clean = target.removesuffix(" (deleted)") if metadata.st_nlink == 0 else target
                            path = Path(clean)
                            root = _root_for(path, roots)
                            if root is None:
                                continue
                            remote = view(root)
                            if remote["status"] != "same_root":
                                excluded["descriptor_root_view_mismatch"] += 1
                                continue
                            pinned = os.open(location, getattr(os, "O_PATH", os.O_RDONLY) | os.O_CLOEXEC)
                            held = os.fstat(pinned)
                            mount_id = _fd_mount(pinned)
                            if _inode(held) != _inode(metadata) or held.st_nlink != metadata.st_nlink:
                                errors["descriptor_changed"] += 1
                                continue
                            evidence = _path_evidence(path, held, mount_id, root, remote)
                            if evidence is None:
                                excluded["descriptor_path_or_mount_mismatch"] += 1
                                continue
                            after = os.stat(location)
                            if (os.readlink(location) != target or _inode(after) != _inode(held)
                                    or after.st_nlink != held.st_nlink):
                                errors["descriptor_changed"] += 1
                                continue
                            candidates.append({"identity": str(held.st_dev) + ":" + str(held.st_ino),
                                "device": held.st_dev, "inode": held.st_ino, "path": clean,
                                "consumer": _owner(path, [root["path"]]),
                                "logical_bytes": held.st_size,
                                "allocated_bytes": getattr(held, "st_blocks", 0) * 512,
                                "unlinked": held.st_nlink == 0, "observed_at": _now(),
                                "holder": {"proc_pid": identity["proc_pid"],
                                    "start_ticks": identity["start_ticks"], "fd": entry.name,
                                    "pid_namespace": identity["pid_namespace"],
                                    "mount_namespace": identity["mount_namespace"],
                                    "mount_id": mount_id, "path": clean,
                                    "consumer": _owner(path, [root["path"]]),
                                    "selection_basis": evidence,
                                    "selected_root": _public_root(root),
                                    "process_root": dict(remote)}})
                        except (OSError, ValueError) as exc:
                            errors[type(exc).__name__] += 1
                        finally:
                            if pinned is not None:
                                os.close(pinned)
            except OSError as exc:
                errors[type(exc).__name__] += 1

            if cwd_owner is None and not candidates:
                continue
            try:
